CREATE OR REPLACE FUNCTION netunim_internal.apply_restore_group_current(p_restore_group_id uuid)
 RETURNS TABLE(restore_group_id uuid, phase text, main_revision bigint, checks_revision bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_owner uuid:=auth.uid();v_group netunim_internal.restore_operation_groups%rowtype;v_main record;v_checks record;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
  select * into v_group from netunim_internal.restore_operation_groups g where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id for update;
  if not found then raise exception 'restore_group_missing' using errcode='P0002';end if;
  if v_group.phase='completed' then
    select applied_revision into main_revision from netunim_internal.document_sync_operations where owner_id=v_owner and domain=v_group.app_site and document_name=v_group.main_document_name and operation_id=v_group.main_operation_id;
    if v_group.checks_state is not null then select applied_revision into checks_revision from netunim_internal.document_sync_operations where owner_id=v_owner and domain='shared-checks' and document_name=v_group.checks_document_name and operation_id=v_group.checks_operation_id;end if;
    restore_group_id:=v_group.restore_group_id;phase:=v_group.phase;return next;return;
  end if;
  perform set_config('app.destructive_operation_kind','restore',true);
  update netunim_internal.restore_operation_groups as g set phase='main_pending',updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  perform netunim_internal.capture_safety_snapshot(v_owner,v_group.app_site,v_group.main_document_name,v_group.main_operation_id,'restore',v_group.restore_group_id);
  if v_group.app_site='orders' then
    select * into v_main from netunim_internal.save_order_management_document_current(v_group.main_document_name,v_group.main_base_revision,v_group.main_state,v_group.main_operation_id,v_group.main_delete_intents,v_group.audit||jsonb_build_object('mutationType','restore','restoreGroupId',v_group.restore_group_id));
  else
    select * into v_main from netunim_internal.save_kupa_document_current(v_group.main_document_name,v_group.main_base_revision,v_group.main_state,v_group.main_operation_id,v_group.main_delete_intents,v_group.audit||jsonb_build_object('mutationType','restore','restoreGroupId',v_group.restore_group_id));
  end if;
  update netunim_internal.restore_operation_groups as g set phase='main_acked',updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  if v_group.checks_state is not null then
    update netunim_internal.restore_operation_groups as g set phase='checks_pending',updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
    perform netunim_internal.capture_safety_snapshot(v_owner,'shared-checks',v_group.checks_document_name,v_group.checks_operation_id,'restore',v_group.restore_group_id);
    select * into v_checks from netunim_internal.save_shared_checks_document_current(v_group.checks_document_name,v_group.checks_base_revision,v_group.checks_state,v_group.checks_operation_id,v_group.checks_delete_ids,v_group.audit||jsonb_build_object('mutationType','restore','restoreGroupId',v_group.restore_group_id));
    update netunim_internal.restore_operation_groups as g set phase='checks_acked',updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  end if;
  perform set_config('app.destructive_operation_kind','',true);
  update netunim_internal.restore_operation_groups as g set phase='completed',completed_at=now(),updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  restore_group_id:=v_group.restore_group_id;phase:='completed';main_revision:=v_main.revision;
  checks_revision:=null;
  if v_group.checks_state is not null then checks_revision:=v_checks.revision;end if;
  return next;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.assert_document_invariants(p_domain text, p_state jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'netunim_internal'
AS $function$
declare v_path text;
begin
  if p_state is null or jsonb_typeof(p_state) is distinct from 'object' then
    raise exception 'invalid_document_state' using errcode='22023',detail=p_domain;
  end if;
  if p_domain='orders' then
    if p_state?'checks' then raise exception 'orders_state_contains_checks' using errcode='22023'; end if;
    foreach v_path in array array[
      'suppliers','transactions','customerDebts','customerOrders',
      'serviceCalls','notes','inventoryItems','inventoryEvents','warehouseOrders'
    ] loop perform netunim_internal.assert_entity_array_ids(p_state,string_to_array(v_path,'.'),true);end loop;
    if jsonb_typeof(p_state->'inventoryCategoryOrder') is distinct from 'array' then raise exception 'invalid_order_configuration' using errcode='22023';end if;
    -- Legacy single-sheet documents remain readable. Workbook documents must
    -- keep every child attached to an existing, nonempty named sheet.
    if p_state?'notesSheet' then
      perform netunim_internal.assert_entity_array_ids(p_state,array['notesSheet','rows'],true);
      perform netunim_internal.assert_entity_array_ids(p_state,array['notesSheet','columns'],true);
      perform netunim_internal.assert_entity_array_ids(p_state,array['notesSheet','sheets'],true);
      if jsonb_array_length(p_state#>'{notesSheet,sheets}')=0 or exists(
        select 1 from jsonb_array_elements(p_state#>'{notesSheet,sheets}') s
        where jsonb_typeof(s->'name') is distinct from 'string' or nullif(btrim(s->>'name'),'') is null
      ) then raise exception 'invalid_notes_workbook' using errcode='22023';end if;
      foreach v_path in array array['rows','columns'] loop
        if exists(select 1 from jsonb_array_elements(p_state#>array['notesSheet',v_path]) child
          where not exists(select 1 from jsonb_array_elements(p_state#>'{notesSheet,sheets}') sheet where sheet->>'id'=child->>'sheetId'))
        then raise exception 'orphan_notes_sheet_entity' using errcode='22023',detail=v_path;end if;
      end loop;
    end if;
  elsif p_domain='kupa' then
    if p_state?'checks' then raise exception 'kupa_state_contains_checks' using errcode='22023'; end if;
    foreach v_path in array array[
      'credits','cash','rights','notes','expenses','cards'
    ] loop perform netunim_internal.assert_entity_array_ids(p_state,string_to_array(v_path,'.'),true);end loop;
    -- Legacy single-sheet documents remain readable. Workbook documents must
    -- keep every child attached to an existing, nonempty named sheet.
    if p_state?'notesSheet' then
      perform netunim_internal.assert_entity_array_ids(p_state,array['notesSheet','rows'],true);
      perform netunim_internal.assert_entity_array_ids(p_state,array['notesSheet','columns'],true);
    end if;
    if p_state#>'{notesSheet,sheets}' is not null then
      perform netunim_internal.assert_entity_array_ids(p_state,array['notesSheet','sheets'],true);
      if jsonb_array_length(p_state#>'{notesSheet,sheets}')=0 or exists(
        select 1 from jsonb_array_elements(p_state#>'{notesSheet,sheets}') s
        where jsonb_typeof(s->'name') is distinct from 'string' or nullif(btrim(s->>'name'),'') is null
      ) then raise exception 'invalid_notes_workbook' using errcode='22023';end if;
      foreach v_path in array array['rows','columns'] loop
        if exists(select 1 from jsonb_array_elements(p_state#>array['notesSheet',v_path]) child
          where not exists(select 1 from jsonb_array_elements(p_state#>'{notesSheet,sheets}') sheet where sheet->>'id'=child->>'sheetId'))
        then raise exception 'orphan_notes_sheet_entity' using errcode='22023',detail=v_path;end if;
      end loop;
    end if;
    if jsonb_typeof(p_state->'bank') is distinct from 'object'
       or jsonb_typeof(p_state#>'{bank,adjustments}') is distinct from 'array' then
      raise exception 'invalid_kupa_bank_state' using errcode='22023';
    end if;
  elsif p_domain='shared-checks' then
    perform netunim_internal.assert_entity_array_ids(p_state,array['checks'],true);
    if jsonb_typeof(p_state->'bankEvents') is distinct from 'array' then raise exception 'invalid_shared_checks_events' using errcode='22023';end if;
  else raise exception 'invalid_document_domain' using errcode='22023',detail=p_domain;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.assert_entity_array_ids(p_state jsonb, p_path text[], p_required boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare v_rows jsonb;v_path text:=array_to_string(p_path,'.');
begin
  v_rows:=p_state#>p_path;
  if v_rows is null and not p_required then return; end if;
  if jsonb_typeof(v_rows) is distinct from 'array' then
    raise exception 'entity_collection_required' using errcode='22023',detail=v_path;
  end if;
  if exists(select 1 from jsonb_array_elements(v_rows) r(value)
    where jsonb_typeof(r.value) is distinct from 'object'
       or jsonb_typeof(r.value->'id') is distinct from 'string'
       or nullif(btrim(r.value->>'id'),'') is null
       or r.value->>'id' is distinct from btrim(r.value->>'id')) then
    raise exception 'entity_id_missing_or_blank' using errcode='22023',detail=v_path;
  end if;
  if exists(select 1 from (
    select btrim(r.value->>'id') id,count(*) n from jsonb_array_elements(v_rows) r(value)
    group by btrim(r.value->>'id') having count(*)>1
  ) duplicates) then
    raise exception 'duplicate_entity_id' using errcode='22023',detail=v_path;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.assert_finance_sync_fence(p_lease_name text, p_lease_token text, p_fence_epoch bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare l public.finance_sync_leases%rowtype;v_owner uuid:=auth.uid();
begin
 if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
 -- Keep the row locked until the publication transaction commits. Recheck time after the lock.
 select * into l from public.finance_sync_leases where owner_id=v_owner and lease_name=p_lease_name for update;
 if not found or p_lease_token is distinct from l.lease_token or p_fence_epoch is distinct from l.fence_epoch or l.leased_until<=clock_timestamp() then
  raise exception 'stale_finance_sync_fence' using errcode='PT409';
 end if;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.assert_spreadsheet(p_state jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare v_part text;v_row jsonb;v_cell record;
begin
  if jsonb_typeof(p_state) is distinct from 'object' or p_state->'version' is distinct from '2'::jsonb then raise exception 'invalid_spreadsheet_version' using errcode='22023';end if;
  foreach v_part in array array['sheets','columns','rows'] loop
    perform netunim_internal.assert_entity_array_ids(p_state,array[v_part],true);
  end loop;
  if exists(select 1 from (select x->>'id' id from jsonb_array_elements((p_state->'sheets')||(p_state->'columns')||(p_state->'rows')) x) all_ids group by id having count(*)>1) then raise exception 'duplicate_spreadsheet_id' using errcode='22023';end if;
  if jsonb_array_length(p_state->'sheets')=0 then raise exception 'empty_spreadsheet' using errcode='22023';end if;
  for v_row in select value from jsonb_array_elements(p_state->'sheets') loop
    if jsonb_typeof(v_row->'name') is distinct from 'string' or nullif(btrim(v_row->>'name'),'') is null then raise exception 'invalid_spreadsheet_name' using errcode='22023';end if;
    if not exists(select 1 from jsonb_array_elements(p_state->'columns') c where c->>'sheetId'=v_row->>'id') then raise exception 'empty_spreadsheet_columns' using errcode='22023';end if;
  end loop;
  for v_row in select value from jsonb_array_elements(p_state->'columns') loop
    if jsonb_typeof(v_row->'title') is distinct from 'string' or jsonb_typeof(v_row->'sheetId') is distinct from 'string' or v_row->>'type' not in ('text','number') or v_row->>'type' is null
      or jsonb_typeof(v_row->'width') is distinct from 'number' or (v_row->>'width')::numeric not between 70 and 520
      or trunc((v_row->>'width')::numeric)<>(v_row->>'width')::numeric
      or not exists(select 1 from jsonb_array_elements(p_state->'sheets') s where s->>'id'=v_row->>'sheetId')
    then raise exception 'invalid_spreadsheet_column' using errcode='22023';end if;
  end loop;
  for v_row in select value from jsonb_array_elements(p_state->'rows') loop
    if jsonb_typeof(v_row->'cells') is distinct from 'object' or jsonb_typeof(v_row->'sheetId') is distinct from 'string' or not exists(select 1 from jsonb_array_elements(p_state->'sheets') s where s->>'id'=v_row->>'sheetId') then raise exception 'invalid_spreadsheet_row' using errcode='22023';end if;
    for v_cell in select * from jsonb_each(v_row->'cells') loop
      if jsonb_typeof(v_cell.value) is distinct from 'string' or not exists(select 1 from jsonb_array_elements(p_state->'columns') c where c->>'id'=v_cell.key and c->>'sheetId'=v_row->>'sheetId') then raise exception 'orphan_spreadsheet_cell' using errcode='22023';end if;
    end loop;
  end loop;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.canonical_delete_intents(p_intents jsonb, p_allowed text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_key text;
  v_value jsonb;
  v_clean jsonb;
  v_out jsonb := '{}'::jsonb;
begin
  if p_intents is null then return v_out; end if;
  if jsonb_typeof(p_intents) is distinct from 'object' then
    raise exception 'invalid_delete_intents' using errcode='22023';
  end if;
  for v_key,v_value in select key,value from jsonb_each(p_intents) loop
    if not (v_key = any(p_allowed)) then
      raise exception 'invalid_delete_intent_domain' using errcode='22023', detail=v_key;
    end if;
    if jsonb_typeof(v_value) is distinct from 'array' then
      raise exception 'invalid_delete_intent_ids' using errcode='22023', detail=v_key;
    end if;
    if exists (
      select 1 from jsonb_array_elements(v_value) j(value)
      where jsonb_typeof(j.value) is distinct from 'string'
         or nullif(btrim(j.value #>> '{}'),'') is null
    ) then
      raise exception 'invalid_delete_intent_ids' using errcode='22023', detail=v_key;
    end if;
    select coalesce(jsonb_agg(id order by id),'[]'::jsonb)
      into v_clean
    from (select distinct btrim(j.value #>> '{}') id from jsonb_array_elements(v_value) j(value)) q;
    if jsonb_array_length(v_clean) <> jsonb_array_length(v_value) then
      raise exception 'duplicate_delete_intent_id' using errcode='22023', detail=v_key;
    end if;
    if jsonb_array_length(v_clean)>0 then v_out:=v_out||jsonb_build_object(v_key,v_clean); end if;
  end loop;
  return v_out;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.capture_safety_snapshot(p_owner uuid, p_domain text, p_document_name text, p_operation_id text, p_kind text, p_restore_group_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_revision bigint;v_state jsonb;
begin
  if auth.uid() is null or p_owner is distinct from auth.uid() then raise exception 'snapshot_owner_mismatch' using errcode='42501';end if;
  if p_domain='orders' then select revision,state into v_revision,v_state from public.order_management_documents where owner_id=p_owner and document_name=p_document_name;
  elsif p_domain='kupa' then select revision,state into v_revision,v_state from public.kupa_documents where owner_id=p_owner and document_name=p_document_name;
  elsif p_domain='shared-checks' then select revision,state into v_revision,v_state from public.shared_checks_documents where owner_id=p_owner and document_name=p_document_name;
  else raise exception 'invalid_document_domain' using errcode='22023';end if;
  if v_revision is not null then insert into netunim_internal.safety_snapshots(owner_id,domain,document_name,operation_id,restore_group_id,revision,state,operation_kind)
    values(p_owner,p_domain,p_document_name,p_operation_id,p_restore_group_id,v_revision,v_state,p_kind) on conflict do nothing;end if;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.check_bank_claim_members(p_claim netunim_internal.check_bank_claims)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare item jsonb; matches jsonb; member jsonb; rows jsonb:='[]'; used jsonb:='[]'; current_check jsonb; enriched jsonb:='[]';
begin
  if p_claim.bank_members is null then return p_claim.members; end if;
  -- Filling an originally blank manual number can resolve an old equal-value
  -- group. Names/amounts remain the original evidence; only compatible identity
  -- enrichment from the still-linked, automatically tracked check is admitted.
  for member in select value from jsonb_array_elements(p_claim.members) loop
    if netunim_internal.check_bank_number(member->>'checkNumber')='' then
      select c into current_check from public.shared_checks_documents d cross join lateral jsonb_array_elements(d.state->'checks') c
        where d.owner_id=p_claim.owner_id and d.document_name=p_claim.document_name and c->>'id'=member->>'id'
          and coalesce(c->>'bankAutomationDisabled','false')<>'true'
          and ((c->'bankMatch'->>'transactionId')=p_claim.transaction_id::text or p_claim.previous_transaction_ids ? (c->'bankMatch'->>'transactionId'))
          and netunim_internal.check_bank_number(c->>'checkNumber')<>''
          and netunim_internal.check_bank_money(c->>'amount')=netunim_internal.check_bank_money(member->>'amount')
          and coalesce(c->>'account','עסקי')=coalesce(member->>'account','עסקי');
      if found and (select count(*) from jsonb_array_elements(p_claim.bank_members) i where netunim_internal.check_bank_same_item(current_check,i))=1 then
        member:=member||jsonb_build_object('checkNumber',current_check->>'checkNumber');
      end if;
    end if;
    enriched:=enriched||jsonb_build_array(member);
  end loop;
  for item in select value from jsonb_array_elements(p_claim.bank_members) loop
    select coalesce(jsonb_agg(c),'[]') into matches from jsonb_array_elements(enriched) c
      where netunim_internal.check_bank_item_matches(coalesce(nullif(c->'bankItem','null'::jsonb),c),item) and not (used ? (c->>'id'));
    if jsonb_array_length(matches)=1 then member:=matches->0;used:=used||jsonb_build_array(member->>'id');
    else member:=jsonb_build_object('id','#bank:'||md5(item::text),'name','שיק מס׳ '||coalesce(item->>'checkNumber','ללא מספר')); end if;
    rows:=rows||jsonb_build_array(member||item||jsonb_build_object('status','בקופה','dueDate',
      ((p_claim.source_transaction->>'transaction_date')::timestamptz at time zone 'Asia/Jerusalem')::date,
      'account',case p_claim.account_role when 'home' then 'ביתי' else 'עסקי' end));
  end loop;
  return rows;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.check_bank_items(p_tx bank_transactions)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare raw jsonb:=p_tx.check_details->'checkItems'; items jsonb; declared_count numeric;
begin
  if raw is null or raw='[]'::jsonb then return '{"kind":"none","items":[]}'::jsonb; end if;
  if jsonb_typeof(raw)<>'array' then return '{"kind":"invalid","items":[]}'::jsonb; end if;
  if jsonb_array_length(raw)>50 or exists(select 1 from jsonb_array_elements(raw) x where jsonb_typeof(x)<>'object'
    or coalesce(netunim_internal.check_bank_money(x->>'amount'),0)<=0) then return '{"kind":"invalid","items":[]}'::jsonb; end if;
  select jsonb_agg(jsonb_build_object('checkNumber',netunim_internal.check_bank_number(x->>'checkNumber'),
    'bankNumber',netunim_internal.check_bank_number(x->>'bankNumber'),'branchNumber',netunim_internal.check_bank_number(x->>'branchNumber'),
    'accountNumber',netunim_internal.check_bank_number(x->>'accountNumber'),'amount',netunim_internal.check_bank_money(x->>'amount')) order by ord)
    into items from jsonb_array_elements(raw) with ordinality a(x,ord);
  declared_count:=netunim_internal.check_bank_money(p_tx.check_details->>'checkCount');
  if (declared_count is not null and declared_count<>jsonb_array_length(items))
    or (select sum((x->>'amount')::numeric) from jsonb_array_elements(items) x)<>abs(p_tx.amount)
    or exists(select 1 from jsonb_array_elements(items) x group by x having count(*)>1)
    or exists(select 1 from jsonb_array_elements(items) x where x->>'checkNumber'='' and (x->>'bankNumber'='' or x->>'branchNumber'='' or x->>'accountNumber'=''))
    or coalesce(p_tx.check_details->>'warning','')<>'' then return jsonb_build_object('kind','invalid','items',items); end if;
  if jsonb_typeof(p_tx.check_details->'checkNumbers')='array' and exists(
    select 1 from jsonb_array_elements_text(p_tx.check_details->'checkNumbers') n where netunim_internal.check_bank_number(n)<>''
      and not exists(select 1 from jsonb_array_elements(items) x where x->>'checkNumber'=netunim_internal.check_bank_number(n)))
    then return jsonb_build_object('kind','invalid','items',items); end if;
  return jsonb_build_object('kind','valid','items',items);
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.check_bank_pending_compatible(p_pending bank_transactions, p_completed jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare nextrow public.bank_transactions; a jsonb; b jsonb; ak text; bk text;
begin
  ak:=netunim_internal.check_bank_kind(p_pending.description);bk:=netunim_internal.check_bank_kind(p_completed->>'description');
  if ak is null and bk is null then return true; end if;
  if ak is distinct from bk then return false; end if;
  nextrow:=jsonb_populate_record(null::public.bank_transactions,jsonb_build_object('amount',p_completed->'amount','check_details',p_completed->'checkDetails'));
  a:=netunim_internal.check_bank_items(p_pending);b:=netunim_internal.check_bank_items(nextrow);
  if a->>'kind'='invalid' or b->>'kind'='invalid' then return false; end if;
  if a->>'kind'='valid' and b->>'kind'='valid' then
    return jsonb_array_length(a->'items')=jsonb_array_length(b->'items') and not exists(select 1 from jsonb_array_elements(a->'items') x
      where (select count(*) from jsonb_array_elements(b->'items') y where netunim_internal.check_bank_same_item(x,y))<>1);
  end if;
  if jsonb_typeof(p_pending.check_details->'checkNumbers')='array' and jsonb_typeof(p_completed->'checkDetails'->'checkNumbers')='array'
    and p_pending.check_details->'checkNumbers'<>'[]'::jsonb and p_completed->'checkDetails'->'checkNumbers'<>'[]'::jsonb then
    return (select jsonb_agg(netunim_internal.check_bank_number(x) order by netunim_internal.check_bank_number(x)) from jsonb_array_elements_text(p_pending.check_details->'checkNumbers') x)
      =(select jsonb_agg(netunim_internal.check_bank_number(x) order by netunim_internal.check_bank_number(x)) from jsonb_array_elements_text(p_completed->'checkDetails'->'checkNumbers') x);
  end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.check_bank_proposals(p_checks jsonb, p_tx bank_transactions)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare pack jsonb:=netunim_internal.check_bank_items(p_tx); i jsonb; v public.bank_transactions:=p_tx; m jsonb; proposals jsonb:='[]'; provisional_number text:=netunim_internal.check_bank_pending_reference_number(p_tx);
begin
  if pack->>'kind'='valid' then
    for i in select value from jsonb_array_elements(pack->'items') loop
      v.amount:=(i->>'amount')::numeric;
      v.check_details:=jsonb_build_object('checkItems',jsonb_build_array(i),'checkNumbers',case when i->>'checkNumber'='' then '[]'::jsonb else jsonb_build_array(i->>'checkNumber') end,'checkCount',1);
      m:=netunim_internal.check_bank_candidates(p_checks,v);
      if m->>'kind'<>'none' then proposals:=proposals||jsonb_build_array(m||jsonb_build_object('bankItem',i,'slot',md5(i::text),'transactionId',p_tx.id)); end if;
    end loop;
    -- An entirely unnumbered group may be certain as a whole even though its
    -- equal-value members cannot yet be assigned to individual bank rows.
    if not exists(select 1 from jsonb_array_elements(proposals) p where p->>'kind'='unique' or p ? 'warning') then
      m:=netunim_internal.check_bank_candidates(p_checks,p_tx);
      if m->>'kind'='unique' and not exists(select 1 from jsonb_array_elements(m->'candidates') c
        where netunim_internal.check_bank_number(c->>'checkNumber')<>'') then
        proposals:=jsonb_build_array(m||jsonb_build_object('slot','batch','transactionId',p_tx.id));
      end if;
    end if;
  elsif provisional_number<>'' then
    -- Hapoalim direct cheque deposits expose the printed cheque number in the
    -- temporary pending reference. Keep that evidence explicitly provisional:
    -- it can identify the pending check, but it is never final clearing proof.
    i:=jsonb_build_object('checkNumber',provisional_number,'bankNumber','','branchNumber','','accountNumber','','amount',abs(p_tx.amount));
    v.check_details:=jsonb_build_object('kind','deposit','checkItems',jsonb_build_array(i),'checkNumbers',jsonb_build_array(provisional_number),'checkCount',1);
    m:=netunim_internal.check_bank_candidates(p_checks,v);
    if m->>'kind'<>'none' then
      proposals:=jsonb_build_array(m||jsonb_build_object('bankItem',i,'slot','pending-reference','transactionId',p_tx.id,'provisionalReference',true));
    end if;
  else
    m:=netunim_internal.check_bank_candidates(p_checks,p_tx);
    if m->>'kind'<>'none' then proposals:=jsonb_build_array(m||jsonb_build_object('slot','batch','transactionId',p_tx.id)); end if;
  end if;
  return proposals;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.check_bank_prune_history(p_check jsonb, p_at timestamp with time zone, p_requested jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare h jsonb; history jsonb:='[]'; m jsonb:=p_check->'bankMatch'; quiet boolean; requested boolean; expired boolean; current_event boolean;
begin
  for h in select value from jsonb_array_elements(case when jsonb_typeof(p_check->'bankHistory')='array' then p_check->'bankHistory' else '[]'::jsonb end) loop
    current_event:=h->>'eventId'=m->>'eventId';
    quiet:=coalesce(not (h ? 'warning') and (h->>'phase'='cleared' or (h->>'phase'='deposited' and (h->>'autoConfirmed'='true' or h->>'provisionalReference'='true'))),false);
    requested:=coalesce(p_requested ? (h->>'eventId'),false) and
      (not current_event or quiet or p_check->>'bankReview'=m->>'eventId');
    expired:=quiet and netunim_internal.check_bank_date(left(h->>'recordedAt',10)) <= (p_at at time zone 'Asia/Jerusalem')::date-60;
    if coalesce(requested or expired,false) then
      if current_event then p_check:=p_check||jsonb_build_object('bankHistoryHiddenEvent',m->>'eventId'); end if;
    else history:=history||jsonb_build_array(h); end if;
  end loop;
  -- Current evidence can predate history recording; an explicit safe dismissal
  -- must suppress its UI fallback too, without dropping the tracking metadata.
  if coalesce(p_requested ? (m->>'eventId'),false) and
    (p_check->>'bankReview'=m->>'eventId' or (not (m ? 'warning') and
      (m->>'phase'='cleared' or (m->>'phase'='deposited' and (m->>'autoConfirmed'='true' or m->>'provisionalReference'='true'))))) then
    p_check:=p_check||jsonb_build_object('bankHistoryHiddenEvent',m->>'eventId');
  end if;
  return case when p_check ? 'bankHistory' then p_check||jsonb_build_object('bankHistory',history) else p_check end;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.check_bank_remainder(p_claim netunim_internal.check_bank_claims, p_snapshot bank_transaction_snapshots)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare tx public.bank_transactions; candidate public.bank_transactions; original numeric; returned_total numeric:=0;
  source_day date; match jsonb; chosen jsonb; missing jsonb; n int:=0; other_claim netunim_internal.check_bank_claims;
  return_ids jsonb:='[]'; returned_members jsonb:='[]'; contested boolean:=false; source_tx public.bank_transactions;
  other_checks jsonb; pack jsonb; original_members jsonb; remaining jsonb; identity_total numeric; input_claim netunim_internal.check_bank_claims:=p_claim;
begin
  p_claim.members:=netunim_internal.check_bank_claim_members(p_claim);
  original_members:=p_claim.members;
  original:=(p_claim.source_transaction->>'amount')::numeric;
  source_day:=((p_claim.source_transaction->>'transaction_date')::timestamptz at time zone 'Asia/Jerusalem')::date;
  select * into tx from public.bank_transactions where owner_id=p_claim.owner_id and id=p_claim.transaction_id;
  if found and tx.presence_state='present' and tx.last_seen_at=p_snapshot.snapshot_at then
    pack:=netunim_internal.check_bank_items(tx);
    if p_claim.bank_members is not null and pack->>'kind'='valid' then
      select coalesce(jsonb_agg(c->>'id'),'[]'),coalesce(sum((c->>'amount')::numeric),0) into remaining,identity_total
        from jsonb_array_elements(original_members) c where exists(select 1 from jsonb_array_elements(pack->'items') i where netunim_internal.check_bank_same_item(c,i));
      if identity_total<original then
        if exists(select 1 from jsonb_array_elements(input_claim.members) c where not exists(select 1 from jsonb_array_elements(original_members) o where o->>'id'=c->>'id')) then
          return jsonb_build_object('kind','ambiguous','transactionId',tx.id,'originalAmount',original,'observedAmount',tx.amount); end if;
        select coalesce(jsonb_agg(c),'[]') into missing from jsonb_array_elements(original_members) c where not (remaining ? (c->>'id'));
        return jsonb_build_object('kind','reduced','transactionId',tx.id,'originalAmount',original,'observedAmount',identity_total,
          'remainingIds',remaining,'missingMembers',missing,'missingAmount',original-identity_total,'evidence','bank_items');
      end if;
    end if;
    if tx.amount=original then
      source_tx:=tx;
      -- Banks also reduce a deposit by separate return debits instead of editing
      -- the credit. Attribute such debits only to a unique original deposit group.
      for candidate in select b.* from public.bank_transactions b where b.owner_id=p_claim.owner_id
        and b.account_key=p_claim.account_key and b.account_role=p_claim.account_role and b.amount<0 and -b.amount<=original
        and b.status='completed' and b.currency='ILS' and b.presence_state='present' and b.last_seen_at=p_snapshot.snapshot_at
        and netunim_internal.check_bank_kind(b.description)='return'
        and (b.transaction_date at time zone 'Asia/Jerusalem')::date between source_day and least(source_day+30,(p_snapshot.snapshot_at at time zone 'Asia/Jerusalem')::date)
      order by b.id
      loop
        candidate.amount:=-candidate.amount;
        match:=netunim_internal.check_bank_candidates(p_claim.members,candidate);
        if match->>'kind'='none' then continue; end if;
        -- Amounts alone cannot make repeated/ambiguous debits disjoint. Two
        -- returns of the same member must never implicate a different member
        -- whose amount happens to equal their sum.
        if match->>'kind'<>'unique' or exists(select 1 from jsonb_array_elements_text(match->'ids') id
          where returned_members ? id) then contested:=true; end if;
        returned_members:=returned_members||coalesce(match->'ids','[]'::jsonb);
        for other_claim in select l.* from netunim_internal.check_bank_claims l where l.owner_id=p_claim.owner_id
          and l.account_key=p_claim.account_key and l.account_role=p_claim.account_role and l.transaction_id<>p_claim.transaction_id
          and (candidate.transaction_date at time zone 'Asia/Jerusalem')::date between
            ((l.source_transaction->>'transaction_date')::timestamptz at time zone 'Asia/Jerusalem')::date and
            ((l.source_transaction->>'transaction_date')::timestamptz at time zone 'Asia/Jerusalem')::date+30
        loop
          if netunim_internal.check_bank_candidates(netunim_internal.check_bank_claim_members(other_claim),candidate)->>'kind'<>'none' then contested:=true; end if;
        end loop;
        returned_total:=returned_total+candidate.amount;return_ids:=return_ids||jsonb_build_array(candidate.id);
      end loop;
      if returned_total=0 or returned_total>original or contested then
        return jsonb_build_object('kind','full','transactionId',tx.id,'originalAmount',original,'originalIds',p_claim.check_ids);
      end if;
      if returned_total=original then
        return jsonb_build_object('kind','reduced','transactionId',tx.id,'originalAmount',original,'observedAmount',0,
          'remainingIds','[]'::jsonb,'missingMembers',p_claim.members,'missingAmount',original,'evidence','return_debits','returnTransactionIds',return_ids);
      end if;
      -- Each debit already proved a unique disjoint subset. Preserve those IDs
      -- rather than trying to infer the complement from equal amounts again.
      select coalesce(jsonb_agg(c->>'id'),'[]') into remaining from jsonb_array_elements(p_claim.members) c where not (returned_members ? (c->>'id'));
      select coalesce(jsonb_agg(c),'[]') into missing from jsonb_array_elements(p_claim.members) c where returned_members ? (c->>'id');
      return jsonb_build_object('kind','reduced','transactionId',tx.id,'originalAmount',original,'observedAmount',original-returned_total,
        'remainingIds',remaining,'missingMembers',missing,'missingAmount',returned_total,'evidence','return_debits','returnTransactionIds',return_ids);

    else
    if tx.amount<=0 or tx.amount>original or tx.currency<>'ILS' or netunim_internal.check_bank_kind(tx.description) is distinct from 'deposit' then return null; end if;
    chosen:=jsonb_build_object('transactionId',tx.id,'observedAmount',tx.amount);
    end if;
  else
    -- The bank may replace the aggregate row when its amount changes. Require one
    -- unique same-day cheque credit, and check competing original batches as well.
    -- This is an inferred replacement, kept reviewable; it never proves a return.
    for candidate in select b.* from public.bank_transactions b where b.owner_id=p_claim.owner_id
      and b.account_key=p_claim.account_key and b.account_role=p_claim.account_role
      and b.presence_state='present' and b.last_seen_at=p_snapshot.snapshot_at
      and b.status in ('pending','completed') and b.currency='ILS' and b.amount>0 and b.amount<original
      and (b.transaction_date at time zone 'Asia/Jerusalem')::date=source_day
      and netunim_internal.check_bank_kind(b.description)='deposit'
      and not exists(select 1 from netunim_internal.check_bank_claims l where l.owner_id=b.owner_id
        and (l.transaction_id=b.id or l.previous_transaction_ids ? b.id::text))
    loop
      -- A changed nonempty bank reference is contradictory evidence, not a match.
      if coalesce(p_claim.source_transaction->>'bank_reference','') not in ('','0')
        and candidate.bank_reference not in ('','0') and candidate.bank_reference<>p_claim.source_transaction->>'bank_reference'
        and not (netunim_internal.check_bank_items(candidate)->>'kind'='valid' and not exists(
          select 1 from jsonb_array_elements(netunim_internal.check_bank_items(candidate)->'items') i where
            (select count(*) from jsonb_array_elements(p_claim.members) member where netunim_internal.check_bank_same_item(member,i))<>1)) then continue; end if;
      match:=netunim_internal.check_bank_candidates(p_claim.members,candidate);
      if match->>'kind'='none' then continue; end if;
      n:=n+1;tx:=candidate;chosen:=jsonb_build_object('transactionId',candidate.id,'observedAmount',candidate.amount);
      -- A same-day amount can also be a genuinely new deposit. In the absence of
      -- a shared stable reference/serial, any other admissible check explanation
      -- makes the inferred successor unsafe.
      if not ((candidate.bank_reference not in ('','0') and candidate.bank_reference=p_claim.source_transaction->>'bank_reference')
        or (candidate.bank_serial not in ('','0') and candidate.bank_serial=p_claim.source_transaction->>'bank_serial')) then
        select coalesce(jsonb_agg(member),'[]') into other_checks
          from public.shared_checks_documents d cross join lateral jsonb_array_elements(d.state->'checks') member
          where d.owner_id=p_claim.owner_id and d.document_name=p_claim.document_name and not (p_claim.check_ids ? (member->>'id'));
        if netunim_internal.check_bank_candidates(other_checks,candidate)->>'kind'<>'none' then n:=n+1; end if;
      end if;
      for other_claim in select l.* from netunim_internal.check_bank_claims l where l.owner_id=p_claim.owner_id
        and l.account_key=p_claim.account_key and l.account_role=p_claim.account_role and l.transaction_id<>p_claim.transaction_id
        and ((l.source_transaction->>'transaction_date')::timestamptz at time zone 'Asia/Jerusalem')::date=source_day
        and not exists(select 1 from public.bank_transactions b where b.owner_id=l.owner_id and b.id=l.transaction_id and b.presence_state='present')
      loop
        if netunim_internal.check_bank_candidates(netunim_internal.check_bank_claim_members(other_claim),candidate)->>'kind'<>'none' then n:=n+1; end if;
      end loop;
    end loop;
    if n<>1 then return null; end if;
  end if;
  if p_claim.bank_members is not null and exists(select 1 from jsonb_array_elements(input_claim.members) c
    where not exists(select 1 from jsonb_array_elements(original_members) o where o->>'id'=c->>'id')) then
    return chosen||jsonb_build_object('kind','ambiguous','originalAmount',original); end if;
  match:=netunim_internal.check_bank_candidates(p_claim.members,tx);
  if match->>'kind'<>'unique' then return chosen||jsonb_build_object('kind','ambiguous','originalAmount',original); end if;
  select coalesce(jsonb_agg(c),'[]') into missing from jsonb_array_elements(p_claim.members) c where not (match->'ids' ? (c->>'id'));
  return chosen||jsonb_build_object('kind','reduced','originalAmount',original,'remainingIds',match->'ids','missingMembers',missing,
    'missingAmount',original-tx.amount);
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.check_bank_return_matches(p_check jsonb, p_match jsonb, p_return bank_transactions)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare pack jsonb:=netunim_internal.check_bank_items(p_return); identity jsonb:=coalesce(nullif(p_match->'bankItem','null'::jsonb),p_check);
begin
  if netunim_internal.check_bank_number(identity->>'checkNumber')='' then return false; end if;
  if pack->>'kind'='valid' then
    return (select count(*) from jsonb_array_elements(pack->'items') i where netunim_internal.check_bank_same_item(identity,i))=1;
  elsif pack->>'kind'='invalid' then return false; end if;
  return -p_return.amount=netunim_internal.check_bank_money(p_check->>'amount')
    and jsonb_typeof(p_return.check_details->'checkNumbers')='array'
    and exists(select 1 from jsonb_array_elements_text(p_return.check_details->'checkNumbers') n
      where netunim_internal.check_bank_number(n)=netunim_internal.check_bank_number(identity->>'checkNumber'));
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.fenced_impl_merge_bank_transactions(p_account_key text, p_account_role text, p_transactions jsonb)
 RETURNS TABLE(inserted_count integer, updated_count integer, total_count integer)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_owner uuid:=auth.uid();
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('netunim_financial_write:'||v_owner::text,0)) then
    raise exception 'save_busy' using errcode='PT429',hint='Another financial save is already in progress. Retry later.';
  end if;
  perform set_config('lock_timeout','100ms',true);
  begin
    return query select * from netunim_internal.merge_bank_transactions(p_account_key,p_account_role,p_transactions);
  exception when lock_not_available then
    raise exception 'save_busy' using errcode='PT429',hint='A financial row is temporarily locked. Retry later.';
  end;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.fenced_impl_save_bank_sync_snapshot(p_document_name text, p_bank_state jsonb, p_snapshot_token text, p_snapshot_seq bigint)
 RETURNS TABLE(finance_revision bigint, kupa_revision bigint, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_owner uuid:=auth.uid();
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('netunim_financial_write:'||v_owner::text,0)) then
    raise exception 'save_busy' using errcode='PT429',hint='Another financial save is already in progress. Retry later.';
  end if;
  perform set_config('lock_timeout','100ms',true);
  begin
    return query select * from netunim_internal.save_bank_sync_snapshot(p_document_name,p_bank_state,p_snapshot_token,p_snapshot_seq);
  exception when lock_not_available then
    raise exception 'save_busy' using errcode='PT429',hint='A financial row is temporarily locked. Retry later.';
  end;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.fenced_impl_save_finance_sync_document_v5(p_document_name text, p_expected_revision bigint, p_state jsonb, p_operation_id text, p_audit jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_owner uuid:=auth.uid();v_before jsonb;v_result record;v_paths text[]:=array[]::text[];
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
  if p_state is null or jsonb_typeof(p_state) is distinct from 'object' then raise exception 'invalid_finance_state' using errcode='22023';end if;
  select d.state into v_before from public.finance_sync_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
  select * into v_result from netunim_internal.save_finance_sync_document_current(p_document_name,p_expected_revision,p_state,p_operation_id);
  perform netunim_internal.record_operation_audit(v_owner,'finance',p_document_name,p_operation_id,coalesce(p_audit,'{}'::jsonb)||jsonb_build_object('baseRevision',p_expected_revision),coalesce(v_before,p_state),v_result.state,v_paths,null);
  return query select v_result.revision,v_result.updated_at,v_result.state,v_result.operation_replayed,v_result.operation_revision;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.fenced_impl_sync_bank_transactions_snapshot(p_account_key text, p_account_role text, p_transactions jsonb, p_snapshot_at timestamp with time zone, p_coverage_from date, p_coverage_to date, p_complete boolean)
 RETURNS TABLE(inserted_count integer, updated_count integer, total_count integer, missing_count integer, active_missing_count integer, snapshot_stored boolean, baseline_created boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_owner uuid:=auth.uid();
  v_inserted integer:=0;
  v_updated integer:=0;
  v_total integer:=0;
  v_previous_snapshot_at timestamptz;
  v_had_complete_snapshot boolean:=false;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if coalesce(btrim(p_account_key),'')='' or p_account_role not in ('business','home')
     or jsonb_typeof(p_transactions) is distinct from 'array'
     or p_snapshot_at is null then
    raise exception 'invalid_bank_snapshot_input' using errcode='22023';
  end if;
  if coalesce(p_complete,false) and (p_coverage_from is null or p_coverage_to is null or p_coverage_to<p_coverage_from) then
    raise exception 'invalid_bank_snapshot_coverage' using errcode='22023';
  end if;

  -- The public merge boundary owns the shared per-user advisory transaction lock both before and
  -- after core contention hardening. Transaction-scoped advisory locks remain held for this whole
  -- RPC, so merge + reconciliation + snapshot are atomic; any later exception rolls all of it back.
  select m.inserted_count,m.updated_count,m.total_count
    into v_inserted,v_updated,v_total
  from netunim_internal.fenced_impl_merge_bank_transactions(p_account_key,p_account_role,p_transactions) m;

  select s.snapshot_at into v_previous_snapshot_at
  from public.bank_transaction_snapshots s
  where s.owner_id=v_owner and s.account_key=p_account_key and s.account_role=p_account_role
  for update;
  v_had_complete_snapshot:=v_previous_snapshot_at is not null;

  -- A late client cannot mutate presence state after a newer proven-complete bank snapshot. This
  -- applies even to an incomplete read: a stale partial response must not resurrect a row that a
  -- newer complete snapshot already proved missing. Throwing rolls the merge back atomically too.
  if v_previous_snapshot_at is not null and p_snapshot_at<v_previous_snapshot_at then
    raise exception 'bank_snapshot_stale'
      using errcode='40001',hint='A newer complete bank snapshot is already stored. The stale snapshot was not applied.';
  end if;

  -- Rows actually returned by the bank are present. This is safe even for a partial read; absence
  -- is the only fact that is forbidden unless the connector proved the whole requested range.
  -- Reappearance also clears an old acknowledgement so a later disappearance becomes a new incident.
  update public.bank_transactions b set
    presence_state='present',
    last_seen_at=p_snapshot_at,
    missing_since=null,
    missing_acknowledged_at=null
  where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
    and exists (
      select 1 from jsonb_array_elements(p_transactions) x(value)
      where x.value->>'mergeKey'=b.merge_key
    )
    and (
      b.presence_state is distinct from 'present'
      or b.last_seen_at is distinct from p_snapshot_at
      or b.missing_since is not null
      or b.missing_acknowledged_at is not null
    );

  if coalesce(p_complete,false) then
    -- Pre-upgrade archive rows start UNKNOWN. The first complete snapshot is a baseline only: it
    -- cannot manufacture warnings for old history whose prior presence was never proven. Starting
    -- with the second complete snapshot, only previously PRESENT rows inside the connector-declared
    -- coverage window can transition to MISSING.
    if v_had_complete_snapshot then
      update public.bank_transactions b set
        presence_state='missing',
        missing_since=coalesce(b.missing_since,p_snapshot_at)
      where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
        and b.presence_state='present'
        and coalesce(b.transaction_date,b.processed_date)::date between p_coverage_from and p_coverage_to
        and (b.last_seen_at is null or b.last_seen_at<p_snapshot_at)
        and not exists (
          select 1 from jsonb_array_elements(p_transactions) x(value)
          where x.value->>'mergeKey'=b.merge_key
        );
    end if;

    insert into public.bank_transaction_snapshots(
      owner_id,account_key,account_role,snapshot_at,coverage_from,coverage_to,
      transaction_count,transactions,updated_at
    ) values (
      v_owner,p_account_key,p_account_role,p_snapshot_at,p_coverage_from,p_coverage_to,
      jsonb_array_length(p_transactions),p_transactions,now()
    )
    on conflict(owner_id,account_key,account_role) do update set
      snapshot_at=excluded.snapshot_at,
      coverage_from=excluded.coverage_from,
      coverage_to=excluded.coverage_to,
      transaction_count=excluded.transaction_count,
      transactions=excluded.transactions,
      updated_at=now()
    where public.bank_transaction_snapshots.snapshot_at<=excluded.snapshot_at;
  end if;

  select count(*)::integer into missing_count
  from public.bank_transactions b
  where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
    and b.presence_state='missing';

  select count(*)::integer into active_missing_count
  from public.bank_transactions b
  where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
    and b.presence_state='missing' and b.missing_acknowledged_at is null;

  inserted_count:=coalesce(v_inserted,0);
  updated_count:=coalesce(v_updated,0);
  total_count:=coalesce(v_total,0);
  snapshot_stored:=coalesce(p_complete,false);
  baseline_created:=coalesce(p_complete,false) and not v_had_complete_snapshot;
  return next;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.json_collection_counts(p_state jsonb, p_paths text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare v_path text;v_out jsonb:='{}'::jsonb;v_value jsonb;
begin
  foreach v_path in array p_paths loop
    v_value:=p_state#>string_to_array(v_path,'.');
    v_out:=v_out||jsonb_build_object(v_path,case when jsonb_typeof(v_value)='array' then jsonb_array_length(v_value) else 0 end);
  end loop;
  return v_out;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.kupa_delete_intent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare
  v_v4_allowed constant text[]:=array['credits','cash','rights','notes','expenses','notesSheet.rows','notesSheet.columns','notesSheet.sheets'];
  v_allowed constant text[]:=array['credits','cash','rights','notes','expenses','notesSheet.rows','notesSheet.columns','notesSheet.sheets','cards'];
  v_key text;v_old jsonb;v_new jsonb;v_removed jsonb;v_actual jsonb:='{}'::jsonb;v_intended jsonb;v_raw text;v_cards_raw text;
begin
  if tg_op<>'UPDATE' then return new;end if;
  foreach v_key in array v_allowed loop
    v_old:=old.state#>string_to_array(v_key,'.');v_new:=new.state#>string_to_array(v_key,'.');
    if jsonb_typeof(v_old) is distinct from 'array' then v_old:='[]'::jsonb;end if;
    if jsonb_typeof(v_new) is distinct from 'array' then v_new:='[]'::jsonb;end if;
    select coalesce(jsonb_agg(id order by id),'[]'::jsonb) into v_removed from (
      select btrim(o.value->>'id') id from jsonb_array_elements(v_old) o(value)
      where nullif(btrim(o.value->>'id'),'') is not null
        and not exists(select 1 from jsonb_array_elements(v_new) n(value) where btrim(n.value->>'id')=btrim(o.value->>'id'))
    ) removed;
    if jsonb_array_length(v_removed)>0 then v_actual:=v_actual||jsonb_build_object(v_key,v_removed);end if;
  end loop;
  v_raw:=nullif(current_setting('app.kupa_delete_intents',true),'');
  v_cards_raw:=nullif(current_setting('app.kupa_cards_delete_intents',true),'');
  v_intended:=netunim_internal.canonical_delete_intents(coalesce(v_raw::jsonb,'{}'::jsonb),v_v4_allowed)
    ||netunim_internal.canonical_delete_intents(jsonb_build_object('cards',coalesce(v_cards_raw::jsonb,'[]'::jsonb)),array['cards']);
  if v_actual is distinct from v_intended then raise exception 'kupa_delete_intent_mismatch' using errcode='PT422';end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.mass_destructive_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_paths text[];v_path text;v_old jsonb;v_new jsonb;v_removed integer;v_old_count integer;
  v_mode text:=coalesce(current_setting('app.destructive_operation_kind',true),'');
  v_absolute_threshold constant integer:=10;
  v_percentage_min_count constant integer:=3;
  v_percentage_threshold constant numeric:=0.50;
begin
  if tg_op<>'UPDATE' or v_mode in ('bulk-delete','restore','destructive-migration') then return new;end if;
  if tg_table_name='order_management_documents' then
    v_paths:=array['suppliers','transactions','customerDebts','customerOrders','serviceCalls','notes','inventoryItems','inventoryEvents','warehouseOrders','notesSheet.sheets','notesSheet.columns','notesSheet.rows'];
  elsif tg_table_name='kupa_documents' then
    v_paths:=array['credits','cash','rights','notes','expenses','cards','notesSheet.rows','notesSheet.columns','notesSheet.sheets'];
  else v_paths:=array['checks'];end if;
  foreach v_path in array v_paths loop
    v_old:=case when jsonb_typeof(old.state#>string_to_array(v_path,'.'))='array' then old.state#>string_to_array(v_path,'.') else '[]'::jsonb end;
    v_new:=case when jsonb_typeof(new.state#>string_to_array(v_path,'.'))='array' then new.state#>string_to_array(v_path,'.') else '[]'::jsonb end;
    v_old_count:=jsonb_array_length(v_old);
    select count(*) into v_removed from jsonb_array_elements(v_old) o(value)
      where nullif(btrim(o.value->>'id'),'') is not null
        and not exists(select 1 from jsonb_array_elements(v_new) n(value) where btrim(n.value->>'id')=btrim(o.value->>'id'));
    if v_removed>=v_absolute_threshold
       or (v_removed>=v_percentage_min_count and v_old_count>0 and v_removed::numeric/v_old_count>=v_percentage_threshold) then
      raise exception 'mass_delete_requires_dedicated_rpc' using errcode='PT422',detail=v_path,
        hint='Use the dedicated approved bulk-delete or restore RPC.';
    end if;
  end loop;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.merge_bank_transactions(p_account_key text, p_account_role text, p_transactions jsonb)
 RETURNS TABLE(inserted_count integer, updated_count integer, total_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_owner uuid:=auth.uid();
  r jsonb;
  v_id bigint;
  v_inserted int:=0;
  v_updated int:=0;
  v_candidates int;
  v_candidate bigint;
  v_date timestamptz;
  v_processed timestamptz;
  v_amount numeric;
  v_serial text;
  v_reference text;
  v_description text;
  v_memo text;
  v_party_name text;
  v_party_norm text;
  v_detail_digits text;
  v_status text;
  v_balance numeric;
  v_activity integer;
  v_pending_id bigint;
  v_pending_in_source boolean;
  v_direct_pending_reference text;
  v_stale_pending_id bigint;
  v_stale_pending_candidates int;
  v_completed_pack jsonb;
  v_completed_item jsonb;
  v_completed_item_number text;
  v_completed_item_amount numeric;
  v_batch_pending_id bigint;
  v_batch_pending_candidates int;
  v_batch_claim_count int;
  v_batch_claim_safe boolean;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  -- Shared per-user financial writer gate: fail fast instead of filling the PostgREST pool.
  if not pg_try_advisory_xact_lock(
    hashtextextended('netunim_financial_write:' || v_owner::text, 0)
  ) then
    raise exception 'save_busy'
      using errcode = 'PT429',
            hint = 'Another financial save is already in progress. Retry later.';
  end if;
  perform set_config('lock_timeout', '100ms', true);
  if coalesce(btrim(p_account_key),'')='' or p_account_role not in ('business','home') or jsonb_typeof(p_transactions) is distinct from 'array' then raise exception 'invalid_bank_merge_input' using errcode='22023'; end if;

  -- A duplicate merge key means the client could not distinguish two source rows. Fail atomically
  -- instead of silently collapsing financial movements. Fallback rows receive occurrence suffixes.
  if exists (
    select 1
    from jsonb_array_elements(p_transactions) x(value)
    group by x.value->>'mergeKey'
    having coalesce(x.value->>'mergeKey','')='' or count(*)>1
  ) then
    raise exception 'bank_archive_ambiguous_source_identity'
      using errcode='22023', hint='The bank returned rows that cannot be given unique stable identities. No archive rows were changed.';
  end if;

  for r in select value from jsonb_array_elements(p_transactions) loop
    if nullif(r->>'amount','') is null then raise exception 'invalid_bank_transaction_amount' using errcode='22023'; end if;
    v_date:=nullif(r->>'date','')::timestamptz;
    v_processed:=nullif(r->>'processedDate','')::timestamptz;
    v_amount:=(r->>'amount')::numeric;
    v_serial:=coalesce(r->>'bankSerial','');
    v_reference:=coalesce(r->>'bankReference','');
    v_description:=coalesce(r->>'description','');
    v_memo:=coalesce(r->>'memo','');
    v_party_name:=coalesce(r->>'partyName','');
    v_party_norm:=lower(regexp_replace(btrim(v_party_name),'[[:space:]]+',' ','g'));
    v_detail_digits:=regexp_replace(coalesce(nullif(r->>'messageDetail',''),r->>'memo',''),'[^0-9]','','g');
    v_status:=case when r->>'status'='pending' then 'pending' else 'completed' end;
    v_balance:=nullif(r->>'balanceAfter','')::numeric;
    v_activity:=nullif(r->>'activityTypeCode','')::integer;
    -- Reuse the already-reviewed strict provisional-reference classifier instead of duplicating
    -- its Hapoalim-shape rules here. The JSON keys are mapped explicitly to the archive row type.
    v_direct_pending_reference:=netunim_internal.check_bank_pending_reference_number(jsonb_populate_record(
      null::public.bank_transactions,jsonb_build_object(
        'status',v_status,'amount',v_amount,'currency',coalesce(nullif(r->>'currency',''),'ILS'),
        'cheque',coalesce((r->>'cheque')::boolean,false),'activity_type_code',v_activity,
        'bank_serial',v_serial,'description',v_description,'check_details',r->'checkDetails',
        'bank_reference',v_reference)));
    v_id:=null;
    v_pending_id:=null;
    v_pending_in_source:=false;

    -- Hapoalim reference numbers are not globally unique. The bank serial is day-scoped and is
    -- the strongest stable identifier available for completed rows, so date is part of every match.
    if v_date is not null and v_serial not in ('','0') then
      select count(*),min(b.id) into v_candidates,v_candidate
      from public.bank_transactions b
      where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
        and b.transaction_date::date=v_date::date and b.bank_serial=v_serial and b.amount=v_amount
        and not exists(select 1 from jsonb_array_elements(p_transactions) src(value)
          where src.value->>'mergeKey'=b.merge_key);
      if v_candidates>1 then
        raise exception 'bank_archive_existing_identity_collision'
          using errcode='40001', hint='More than one archived row matches the same bank date/serial/amount identity. No merge was committed.';
      elsif v_candidates=1 then v_id:=v_candidate; end if;
    end if;
    if v_id is null and v_date is not null and v_reference<>'' then
      select count(*),min(b.id) into v_candidates,v_candidate
      from public.bank_transactions b
      where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
        and b.transaction_date::date=v_date::date and b.bank_reference=v_reference and b.amount=v_amount
        and b.description=v_description and b.memo=v_memo
        and not exists(select 1 from jsonb_array_elements(p_transactions) src(value)
          where src.value->>'mergeKey'=b.merge_key);
      if v_candidates>1 then
        raise exception 'bank_archive_existing_identity_collision'
          using errcode='40001', hint='More than one archived row matches the same bank date/reference/amount/content identity. No merge was committed.';
      elsif v_candidates=1 then v_id:=v_candidate; end if;
    end if;

    if v_id is null and coalesce(r->>'mergeKey','')<>'' then
      select count(*),min(b.id) into v_candidates,v_candidate
      from public.bank_transactions b
      where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role and b.merge_key=r->>'mergeKey';
      if v_candidates>1 then
        raise exception 'bank_archive_existing_merge_key_collision'
          using errcode='40001', hint='More than one archived row has the same merge key. No merge was committed.';
      elsif v_candidates=1 then v_id:=v_candidate; end if;
    end if;

    -- Hapoalim can first expose a direct-cheque pending row on the physical deposit day and
    -- later move that SAME pending row to the future business/value day. mergeKey/date are then
    -- different, and the running balance can also move because the bank reorders pending rows.
    -- The processed/value day remains stable. Reuse the old archive id only for the exact strict
    -- provisional-reference shape, exact cheque reference + amount + value day, one candidate,
    -- and only when the old representation is absent from the current bank payload.
    if v_id is null and v_direct_pending_reference<>'' and v_processed is not null then
      select count(*),min(b.id) into v_candidates,v_candidate
      from public.bank_transactions b
      where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
        and b.status='pending' and b.amount=v_amount and b.currency='ILS'
        and netunim_internal.check_bank_pending_reference_number(b)=v_direct_pending_reference
        and b.processed_date is not null
        and (b.processed_date at time zone 'Asia/Jerusalem')::date=(v_processed at time zone 'Asia/Jerusalem')::date
        and not exists(select 1 from jsonb_array_elements(p_transactions) src(value)
          where src.value->>'mergeKey'=b.merge_key);
      if v_candidates=1 then v_id:=v_candidate; end if;
    end if;

    -- A Hapoalim pending row is a temporary state of the same movement. While pending, the bank
    -- commonly returns serial=0 and can later change both the activity label and beneficiary text.
    -- Reference/balance matches remain preferred. Instant credits (including Zahav-style credits)
    -- get one additional fail-closed identity: same amount, same/adjacent bank day, compatible
    -- activity direction, a long beneficiary-name phrase contained in the other state, and the
    -- same >=8-digit account suffix extracted from messageDetail (memo is only a fallback source).
    -- The candidate must still be UNIQUE; ambiguity deliberately leaves rows separate.
    if v_status='completed' and v_date is not null then
      select count(*),min(b.id) into v_candidates,v_candidate
      from public.bank_transactions b
      cross join lateral (
        select
          lower(regexp_replace(btrim(coalesce(b.party_name,'')),'[[:space:]]+',' ','g')) as pending_party_norm,
          regexp_replace(coalesce(nullif(b.message_detail,''),b.memo,''),'[^0-9]','','g') as pending_detail_digits
      ) hints
      where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
        and b.status='pending' and b.amount=v_amount
        and netunim_internal.check_bank_pending_compatible(b,r)
        and b.transaction_date between (v_date-interval '3 days') and (v_date+interval '3 days')
        and (
          netunim_internal.check_bank_pending_items_equal(b,r)
          or
          (v_reference not in ('','0') and b.bank_reference=v_reference
            and (v_activity is null or b.activity_type_code is null or b.activity_type_code=v_activity))
          or
          (v_balance is not null and v_activity is not null
            and b.balance_after is not distinct from v_balance
            and b.activity_type_code=v_activity
            and (
              b.description=v_description
              or (
                netunim_internal.check_bank_kind(b.description)='deposit'
                and netunim_internal.check_bank_kind(v_description)='deposit'
              )
            ))
          or
          (
            v_amount>0
            and (v_description ~ 'מיידי|זה.?ב' or coalesce(b.description,'') ~ 'מיידי|זה.?ב')
            and b.transaction_date between (v_date-interval '1 day') and (v_date+interval '1 day')
            and (v_activity is null or b.activity_type_code is null or b.activity_type_code=v_activity)
            and length(v_party_norm)>=8 and length(hints.pending_party_norm)>=8
            and array_length(regexp_split_to_array(v_party_norm,'[[:space:]]+'),1)>=2
            and array_length(regexp_split_to_array(hints.pending_party_norm,'[[:space:]]+'),1)>=2
            and (
              position(' '||v_party_norm||' ' in ' '||hints.pending_party_norm||' ')>0
              or position(' '||hints.pending_party_norm||' ' in ' '||v_party_norm||' ')>0
            )
            and length(v_detail_digits)>=8 and length(hints.pending_detail_digits)>=8
            and right(v_detail_digits,least(length(v_detail_digits),length(hints.pending_detail_digits)))
              =right(hints.pending_detail_digits,least(length(v_detail_digits),length(hints.pending_detail_digits)))
          )
        );
      if v_candidates=1 then
        v_pending_id:=v_candidate;

        -- Never delete a pending row that the current bank payload still exposes. The exact merge
        -- key is preferred, but connector upgrades are allowed to change derived client identities,
        -- so a conservative stable-facts fallback also counts as "still present".
        select exists(
          select 1
          from public.bank_transactions pb
          cross join lateral jsonb_array_elements(p_transactions) x(value)
          where pb.id=v_pending_id and x.value->>'status'='pending'
            and (
              x.value->>'mergeKey'=pb.merge_key
              or (
                nullif(x.value->>'amount','') is not null
                and (x.value->>'amount')::numeric=pb.amount
                and (
                  (coalesce(x.value->>'bankReference','') not in ('','0')
                    and x.value->>'bankReference'=pb.bank_reference)
                  or
                  (nullif(x.value->>'balanceAfter','') is not null
                    and nullif(x.value->>'activityTypeCode','') is not null
                    and (x.value->>'balanceAfter')::numeric is not distinct from pb.balance_after
                    and (x.value->>'activityTypeCode')::integer is not distinct from pb.activity_type_code)
                  or
                  (coalesce(x.value->>'description','')=pb.description
                    and nullif(x.value->>'date','') is not null
                    and (x.value->>'date')::timestamptz between (pb.transaction_date-interval '1 day') and (pb.transaction_date+interval '1 day'))
                )
              )
            )
        ) into v_pending_in_source;

        if not v_pending_in_source and v_id is null then
          v_id:=v_pending_id;
        end if;
      end if;
    end if;

    if v_id is null then
      insert into public.bank_transactions(owner_id,account_key,account_role,merge_key,transaction_date,processed_date,amount,currency,description,memo,party_name,party_headline,message_headline,message_detail,status,balance_after,bank_reference,bank_serial,activity_type_code,cheque,check_details,credit_settlement_details)
      values(v_owner,p_account_key,p_account_role,r->>'mergeKey',v_date,v_processed,v_amount,coalesce(nullif(r->>'currency',''),'ILS'),v_description,coalesce(r->>'memo',''),coalesce(r->>'partyName',''),coalesce(r->>'partyHeadline',''),coalesce(r->>'messageHeadline',''),coalesce(r->>'messageDetail',''),v_status,v_balance,v_reference,v_serial,v_activity,coalesce((r->>'cheque')::boolean,false),r->'checkDetails',r->'creditSettlementDetails')
      returning id into v_id;
      v_inserted:=v_inserted+1;
    else
      update public.bank_transactions b set
        merge_key=coalesce(nullif(r->>'mergeKey',''),b.merge_key),
        transaction_date=coalesce(v_date,b.transaction_date),
        processed_date=coalesce(v_processed,b.processed_date),
        currency=coalesce(nullif(r->>'currency',''),b.currency),
        description=coalesce(nullif(r->>'description',''),b.description),
        memo=coalesce(r->>'memo',b.memo),
        party_name=coalesce(r->>'partyName',b.party_name),
        party_headline=coalesce(r->>'partyHeadline',b.party_headline),
        message_headline=coalesce(r->>'messageHeadline',b.message_headline),
        message_detail=coalesce(r->>'messageDetail',b.message_detail),
        status=case when v_status='pending' and b.status='completed' then b.status else v_status end,
        balance_after=coalesce(v_balance,b.balance_after),
        bank_reference=coalesce(nullif(r->>'bankReference',''),b.bank_reference),
        bank_serial=coalesce(nullif(r->>'bankSerial',''),b.bank_serial),
        activity_type_code=coalesce(v_activity,b.activity_type_code),
        cheque=coalesce((r->>'cheque')::boolean,b.cheque),
        check_details=coalesce(r->'checkDetails',b.check_details),
        credit_settlement_details=coalesce(r->'creditSettlementDetails',b.credit_settlement_details),
        last_changed_at=now()
      where b.id=v_id and (
        b.merge_key is distinct from coalesce(nullif(r->>'mergeKey',''),b.merge_key)
        or b.transaction_date is distinct from coalesce(v_date,b.transaction_date)
        or b.processed_date is distinct from coalesce(v_processed,b.processed_date)
        or b.currency is distinct from coalesce(nullif(r->>'currency',''),b.currency)
        or b.description is distinct from coalesce(nullif(r->>'description',''),b.description)
        or b.memo is distinct from coalesce(r->>'memo',b.memo)
        or b.party_name is distinct from coalesce(r->>'partyName',b.party_name)
        or b.party_headline is distinct from coalesce(r->>'partyHeadline',b.party_headline)
        or b.message_headline is distinct from coalesce(r->>'messageHeadline',b.message_headline)
        or b.message_detail is distinct from coalesce(r->>'messageDetail',b.message_detail)
        or b.status is distinct from (case when v_status='pending' and b.status='completed' then b.status else v_status end)
        or b.balance_after is distinct from coalesce(v_balance,b.balance_after)
        or b.bank_reference is distinct from coalesce(nullif(r->>'bankReference',''),b.bank_reference)
        or b.bank_serial is distinct from coalesce(nullif(r->>'bankSerial',''),b.bank_serial)
        or b.activity_type_code is distinct from coalesce(v_activity,b.activity_type_code)
        or b.cheque is distinct from coalesce((r->>'cheque')::boolean,b.cheque)
        or b.check_details is distinct from coalesce(r->'checkDetails',b.check_details)
        or b.credit_settlement_details is distinct from coalesce(r->'creditSettlementDetails',b.credit_settlement_details)
      );
      if found then v_updated:=v_updated+1; end if;
    end if;

    -- Heal the pre-upgrade false-positive pair: the old deposit-day pending row may already be
    -- stored beside the current value-day pending row. Delete only ONE stale strict provisional
    -- representation with the same cheque reference + amount + processed/value day, and never a
    -- row whose mergeKey is still present in this payload. This preserves genuine simultaneous
    -- source rows and fails closed when historical evidence is ambiguous.
    if v_direct_pending_reference<>'' and v_processed is not null and v_id is not null then
      select count(*),min(b.id) into v_stale_pending_candidates,v_stale_pending_id
      from public.bank_transactions b
      where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
        and b.id<>v_id and b.status='pending' and b.amount=v_amount and b.currency='ILS'
        and netunim_internal.check_bank_pending_reference_number(b)=v_direct_pending_reference
        and b.processed_date is not null
        and (b.processed_date at time zone 'Asia/Jerusalem')::date=(v_processed at time zone 'Asia/Jerusalem')::date
        and not exists(select 1 from jsonb_array_elements(p_transactions) src(value)
          where src.value->>'mergeKey'=b.merge_key);
      if v_stale_pending_candidates=1 then
        perform netunim_internal.move_check_bank_claim(v_stale_pending_id,v_id);
        delete from public.bank_transactions b
        where b.id=v_stale_pending_id and b.owner_id=v_owner and b.account_key=p_account_key
          and b.account_role=p_account_role and b.status='pending'
          and netunim_internal.check_bank_pending_reference_number(b)=v_direct_pending_reference
          and b.amount=v_amount and b.processed_date is not null
          and (b.processed_date at time zone 'Asia/Jerusalem')::date=(v_processed at time zone 'Asia/Jerusalem')::date;
      end if;
    end if;

    -- Heal duplicates created by the previous logic: if this completed row already existed under
    -- its final serial identity, remove only the one uniquely matched stale pending placeholder.
    -- Security-definer ownership keeps DELETE capability inside this RPC; clients are not granted
    -- direct delete permission on the bank archive table.
    if v_status='completed' and v_pending_id is not null and v_pending_id<>v_id and not v_pending_in_source then
      perform netunim_internal.move_check_bank_claim(v_pending_id,v_id);
      delete from public.bank_transactions b
      where b.id=v_pending_id and b.owner_id=v_owner and b.account_key=p_account_key
        and b.account_role=p_account_role and b.status='pending';
    end if;


    -- Hapoalim finalizes a multi-cheque mobile/machine deposit by replacing N separate
    -- direct pending rows (one per cheque, reference=printed cheque number) with ONE completed
    -- row whose aggregate amount is the sum and whose checkItems contains the authoritative
    -- per-cheque numbers/amounts. The ordinary pending->completed identity above cannot match
    -- this representation because each pending child amount differs from the aggregate amount.
    -- Remove each replaced child independently only when the completed item table itself is valid,
    -- the child is a UNIQUE strict provisional-reference row for the same cheque+amount+value day,
    -- and that exact archived representation is absent from the current source payload.
    if v_status='completed' and v_id is not null and v_processed is not null
      and netunim_internal.check_bank_kind(v_description) in ('deposit','redeposit') then
      v_completed_pack:=netunim_internal.check_bank_items(jsonb_populate_record(
        null::public.bank_transactions,jsonb_build_object('amount',v_amount,'check_details',r->'checkDetails')));
      if v_completed_pack->>'kind'='valid' then
        for v_completed_item in select value from jsonb_array_elements(v_completed_pack->'items') loop
          v_completed_item_number:=netunim_internal.check_bank_number(v_completed_item->>'checkNumber');
          v_completed_item_amount:=netunim_internal.check_bank_money(v_completed_item->>'amount');
          if v_completed_item_number<>'' and v_completed_item_amount is not null then
            select count(*),min(b.id) into v_batch_pending_candidates,v_batch_pending_id
            from public.bank_transactions b
            where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
              and b.id<>v_id and b.status='pending' and b.amount=v_completed_item_amount and b.currency='ILS'
              and netunim_internal.check_bank_pending_reference_number(b)=v_completed_item_number
              and b.processed_date is not null
              and (b.processed_date at time zone 'Asia/Jerusalem')::date=(v_processed at time zone 'Asia/Jerusalem')::date
              and not exists(select 1 from jsonb_array_elements(p_transactions) src(value)
                where src.value->>'mergeKey'=b.merge_key
                  or (
                    nullif(src.value->>'amount','') is not null
                    and (src.value->>'amount')::numeric=v_completed_item_amount
                    and nullif(src.value->>'processedDate','') is not null
                    and ((src.value->>'processedDate')::timestamptz at time zone 'Asia/Jerusalem')::date=(v_processed at time zone 'Asia/Jerusalem')::date
                    and netunim_internal.check_bank_pending_reference_number(jsonb_populate_record(
                      null::public.bank_transactions,jsonb_build_object(
                        'status',case when src.value->>'status'='pending' then 'pending' else 'completed' end,
                        'amount',(src.value->>'amount')::numeric,'currency',coalesce(nullif(src.value->>'currency',''),'ILS'),
                        'cheque',coalesce((src.value->>'cheque')::boolean,false),
                        'activity_type_code',nullif(src.value->>'activityTypeCode','')::integer,
                        'bank_serial',coalesce(src.value->>'bankSerial',''),'description',coalesce(src.value->>'description',''),
                        'check_details',src.value->'checkDetails','bank_reference',coalesce(src.value->>'bankReference',''))
                    ))=v_completed_item_number
                  ));

            if v_batch_pending_candidates=1 then
              -- Provisional-reference evidence normally owns no claim. A pre-upgrade amount/date
              -- fallback may still own one exact single-cheque claim; discard only that proven
              -- legacy reservation so the completed structured batch can create the durable claim.
              select count(*) into v_batch_claim_count
              from netunim_internal.check_bank_claims l
              where l.owner_id=v_owner and l.transaction_id=v_batch_pending_id;
              if v_batch_claim_count=1 then
                select exists(
                  select 1 from netunim_internal.check_bank_claims l
                  cross join lateral jsonb_array_elements(l.members) member
                  where l.owner_id=v_owner and l.transaction_id=v_batch_pending_id and not l.conflicted
                    and jsonb_array_length(l.check_ids)=1 and jsonb_array_length(l.members)=1
                    and netunim_internal.check_bank_number(member->>'checkNumber')=v_completed_item_number
                    and netunim_internal.check_bank_money(member->>'amount')=v_completed_item_amount
                ) into v_batch_claim_safe;
                if not v_batch_claim_safe then
                  continue;
                end if;
                delete from netunim_internal.check_bank_claims l
                where l.owner_id=v_owner and l.transaction_id=v_batch_pending_id and not l.conflicted;
              end if;

              delete from public.bank_transactions b
              where b.id=v_batch_pending_id and b.owner_id=v_owner and b.account_key=p_account_key
                and b.account_role=p_account_role and b.status='pending' and b.currency='ILS'
                and b.amount=v_completed_item_amount
                and netunim_internal.check_bank_pending_reference_number(b)=v_completed_item_number
                and b.processed_date is not null
                and (b.processed_date at time zone 'Asia/Jerusalem')::date=(v_processed at time zone 'Asia/Jerusalem')::date
                and not exists(select 1 from jsonb_array_elements(p_transactions) src(value)
                  where src.value->>'mergeKey'=b.merge_key
                  or (
                    nullif(src.value->>'amount','') is not null
                    and (src.value->>'amount')::numeric=v_completed_item_amount
                    and nullif(src.value->>'processedDate','') is not null
                    and ((src.value->>'processedDate')::timestamptz at time zone 'Asia/Jerusalem')::date=(v_processed at time zone 'Asia/Jerusalem')::date
                    and netunim_internal.check_bank_pending_reference_number(jsonb_populate_record(
                      null::public.bank_transactions,jsonb_build_object(
                        'status',case when src.value->>'status'='pending' then 'pending' else 'completed' end,
                        'amount',(src.value->>'amount')::numeric,'currency',coalesce(nullif(src.value->>'currency',''),'ILS'),
                        'cheque',coalesce((src.value->>'cheque')::boolean,false),
                        'activity_type_code',nullif(src.value->>'activityTypeCode','')::integer,
                        'bank_serial',coalesce(src.value->>'bankSerial',''),'description',coalesce(src.value->>'description',''),
                        'check_details',src.value->'checkDetails','bank_reference',coalesce(src.value->>'bankReference',''))
                    ))=v_completed_item_number
                  ));
            end if;
          end if;
        end loop;
      end if;
    end if;
  end loop;
  -- Self-verify the statement before returning. If any source row failed to become the exact
  -- archived row for its merge key, raise and let PostgreSQL roll the whole RPC statement back.
  if exists (
    select 1
    from jsonb_array_elements(p_transactions) x(value)
    where not exists (
      select 1 from public.bank_transactions b
      where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role
        and b.merge_key=x.value->>'mergeKey'
        and (nullif(x.value->>'date','') is null or b.transaction_date is not distinct from (x.value->>'date')::timestamptz)
        and (nullif(x.value->>'processedDate','') is null or b.processed_date is not distinct from (x.value->>'processedDate')::timestamptz)
        and b.amount=(x.value->>'amount')::numeric
        and b.description=coalesce(x.value->>'description','')
        and b.memo=coalesce(x.value->>'memo','')
        and (coalesce(x.value->>'bankReference','')='' or b.bank_reference=x.value->>'bankReference')
        and (coalesce(x.value->>'bankSerial','')='' or b.bank_serial=x.value->>'bankSerial')
        and (case when x.value->>'status'='pending' then b.status in ('pending','completed') else b.status='completed' end)
    )
  ) then
    raise exception 'bank_archive_merge_verification_failed'
      using errcode='40001', hint='The transaction merge did not reproduce every bank row exactly. The entire RPC was rolled back.';
  end if;

  select count(*)::int into total_count from public.bank_transactions b where b.owner_id=v_owner and b.account_key=p_account_key and b.account_role=p_account_role;
  inserted_count:=v_inserted; updated_count:=v_updated; return next;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.order_management_delete_intent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare
  v_allowed constant text[] := array['suppliers','transactions','customerDebts','customerOrders','serviceCalls','notes','inventoryItems','inventoryEvents','warehouseOrders','notesSheet.sheets','notesSheet.columns','notesSheet.rows'];
  v_key text;
  v_old jsonb;
  v_new jsonb;
  v_removed jsonb;
  v_actual jsonb := '{}'::jsonb;
  v_intended jsonb;
  v_raw text;
begin
  if tg_op <> 'UPDATE' then return new; end if;
  foreach v_key in array v_allowed loop
    v_old:=case when jsonb_typeof(old.state#>string_to_array(v_key,'.'))='array' then old.state#>string_to_array(v_key,'.') else '[]'::jsonb end;
    v_new:=case when jsonb_typeof(new.state#>string_to_array(v_key,'.'))='array' then new.state#>string_to_array(v_key,'.') else '[]'::jsonb end;
    select coalesce(jsonb_agg(id order by id),'[]'::jsonb) into v_removed
    from (
      select o.value->>'id' id
      from jsonb_array_elements(v_old) o(value)
      where nullif(btrim(o.value->>'id'),'') is not null
        and not exists (select 1 from jsonb_array_elements(v_new) n(value) where n.value->>'id'=o.value->>'id')
    ) q;
    if jsonb_array_length(v_removed)>0 then v_actual:=v_actual||jsonb_build_object(v_key,v_removed); end if;
  end loop;
  v_raw:=nullif(current_setting('app.order_management_delete_intents',true),'');
  v_intended:=netunim_internal.canonical_delete_intents(coalesce(v_raw::jsonb,'{}'::jsonb),v_allowed);
  if v_actual is distinct from v_intended then
    raise exception 'order_management_delete_intent_mismatch'
      using errcode='PT422', hint='Record deletion requires exact explicit delete intents.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.protect_check_bank_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c jsonb; oldc jsonb; rows jsonb:='[]'; linked boolean; material_changed boolean; number_changed boolean; requested jsonb;
begin
  if current_setting('app.check_bank_reconcile',true)='1' then return new; end if;
  for c in select value from jsonb_array_elements(new.state->'checks') loop
    select value into oldc from jsonb_array_elements(case when tg_op='UPDATE' then old.state->'checks' else '[]'::jsonb end)
      where value->>'id'=c->>'id';
    requested:=case when jsonb_typeof(c->'bankHistoryDismiss')='array' then c->'bankHistoryDismiss' else '[]'::jsonb end;
    c:=c-'bankMatch'-'bankHistory'-'bankHistoryDismiss'-'bankHistoryHiddenEvent';
    if oldc ? 'bankHistoryHiddenEvent' then c:=c||jsonb_build_object('bankHistoryHiddenEvent',oldc->'bankHistoryHiddenEvent'); end if;
    if oldc ? 'bankHistory' then c:=c||jsonb_build_object('bankHistory',oldc->'bankHistory'); end if;
    material_changed:=(c->>'status',c->>'amount',c->>'dueDate',coalesce(c->>'account','עסקי'))
      is distinct from (oldc->>'status',oldc->>'amount',oldc->>'dueDate',coalesce(oldc->>'account','עסקי'));
    number_changed:=netunim_internal.check_bank_number(c->>'checkNumber')
      is distinct from netunim_internal.check_bank_number(oldc->>'checkNumber');
    select exists(select 1 from netunim_internal.check_bank_claims l
      where l.owner_id=new.owner_id and l.document_name=new.document_name and l.check_ids ? (c->>'id')
        and (l.transaction_id::text=oldc->'bankMatch'->>'transactionId'
          or l.previous_transaction_ids ? (oldc->'bankMatch'->>'transactionId'))) into linked;

    if linked then
      c:=c||jsonb_build_object('bankMatch',oldc->'bankMatch');
      if material_changed or (number_changed and (
        netunim_internal.check_bank_number(oldc->>'checkNumber')<>''
        or (coalesce(oldc->'bankMatch'->'bankItem'->>'checkNumber','')<>''
          and netunim_internal.check_bank_number(c->>'checkNumber')<>oldc->'bankMatch'->'bankItem'->>'checkNumber'))) then
        c:=c||jsonb_build_object('bankAutomationDisabled',true,
          'bankMatch',((oldc->'bankMatch')-'autoConfirmed')||'{"phase":"manual"}'::jsonb);
      end if;
    elsif oldc ? 'bankMatch' and not material_changed and not number_changed then
      -- Unchanged advisories retain their acknowledgement; editing their inputs
      -- discards the old proposal and lets the next complete snapshot reassess.
      c:=c||jsonb_build_object('bankMatch',oldc->'bankMatch');
    end if;

    if not c ? 'bankAutomationDisabled' and oldc ? 'bankAutomationDisabled' then
      c:=c||jsonb_build_object('bankAutomationDisabled',oldc->'bankAutomationDisabled');
    end if;
    if not c ? 'bankReview' and oldc ? 'bankReview' then c:=c||jsonb_build_object('bankReview',oldc->'bankReview'); end if;
    if c->>'bankAutomationDisabled'='true' and c ? 'bankMatch' then
      c:=jsonb_set(c,'{bankMatch}',((c->'bankMatch')-'autoConfirmed')||'{"phase":"manual"}'::jsonb);
    end if;
    if oldc->>'bankAutomationDisabled'='true' and c->>'bankAutomationDisabled'='false' then
      if linked and c->>'status'='הופקד - במעקב' and c->'bankMatch'->>'phase'='manual' then
        c:=jsonb_set(c,'{bankMatch}',(c->'bankMatch')||jsonb_build_object('phase','deposited',
          'eventId',(c->'bankMatch'->>'transactionId')||':resume:'||clock_timestamp()::text));
      elsif not linked then
        -- Explicit resume of an unclaimed warning starts a fresh search; never
        -- manufacture a deposited link or a null event identity from an advisory.
        c:=c-'bankMatch';
      end if;
    end if;
    c:=netunim_internal.check_bank_prune_history(c,clock_timestamp(),requested);
    rows:=rows||jsonb_build_array(c);
  end loop;
  new.state:=jsonb_set(new.state,'{checks}',rows);
  return new;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.prune_document_backups()
 RETURNS TABLE(rolling_deleted bigint, periodic_deleted bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_table text;v_deleted bigint;
begin
  rolling_deleted:=0;periodic_deleted:=0;
  foreach v_table in array array[
    'order_management_document_backups','kupa_document_backups','shared_checks_document_backups'
  ] loop
    execute pg_catalog.format(
      'with ranked as materialized (
         select id,row_number() over(partition by owner_id,document_name order by saved_at desc,id desc) as recency_rank
         from public.%I
       ),deleted as (
         delete from public.%I target using ranked
         where target.id=ranked.id and ranked.recency_rank>200
         returning target.id
       ) select count(*)::bigint from deleted',v_table,v_table
    ) into v_deleted;
    rolling_deleted:=rolling_deleted+v_deleted;
  end loop;
  foreach v_table in array array[
    'order_management_periodic_backups','kupa_periodic_backups','shared_checks_periodic_backups'
  ] loop
    execute pg_catalog.format(
      'with deleted as (
         delete from public.%I
         where saved_at < statement_timestamp()-interval ''365 days''
         returning id
       ) select count(*)::bigint from deleted',v_table
    ) into v_deleted;
    periodic_deleted:=periodic_deleted+v_deleted;
  end loop;
  return next;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.reconcile_check_bank_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare doc record; tx public.bank_transactions; ret public.bank_transactions; c jsonb; m jsonb;
  rows jsonb; nextrows jsonb; proposals jsonb:='[]'; proposal jsonb; match jsonb; ids jsonb;
  phase text; event text; txday date; clearafter date; returncount int; overlapcount int; claim netunim_internal.check_bank_claims;
  pack jsonb; mapped_item jsonb; mapped_count int; oldclaim netunim_internal.check_bank_claims; already_claimed boolean; number_confirmed boolean;
  batches jsonb:='{}'; remainder jsonb; members jsonb; reduced_survivor boolean; provisional_reference boolean; replacing_provisional_reference boolean;
  legacy_member jsonb; legacy_item jsonb; legacy_number text;
begin
  -- The existing archive RPC supplies authenticated identity and complete, fenced snapshots.
  if auth.uid() is null or new.owner_id<>auth.uid() then return new; end if;
  if tg_op='UPDATE' and new.snapshot_at<=old.snapshot_at then return new; end if;
  if new.snapshot_at>clock_timestamp()+interval '5 minutes' then return new; end if;
  select * into doc from public.shared_checks_documents d where d.owner_id=new.owner_id and d.document_name='main' for update;
  if not found then return new; end if;
  rows:=doc.state->'checks';

  -- Older reconciliation treated an amount-only pending match as a durable claim.
  -- Live Hapoalim evidence now proves that a very specific pending direct-deposit
  -- presentation carries the cheque number in bank_reference. Convert only a
  -- single-member exact-number/amount legacy claim back to provisional evidence,
  -- so the later completed multi-cheque row can replace it atomically.
  for claim in select l.* from netunim_internal.check_bank_claims l where l.owner_id=new.owner_id
    and l.account_key=new.account_key and l.account_role=new.account_role and not l.conflicted
  loop
    select * into tx from public.bank_transactions where id=claim.transaction_id and owner_id=new.owner_id;
    legacy_number:=case when found then netunim_internal.check_bank_pending_reference_number(tx) else '' end;
    if legacy_number<>'' and jsonb_array_length(claim.check_ids)=1 and jsonb_array_length(claim.members)=1 then
      select value into legacy_member from jsonb_array_elements(claim.members) member
        where netunim_internal.check_bank_number(member->>'checkNumber')=legacy_number
          and netunim_internal.check_bank_money(member->>'amount')=abs(tx.amount) limit 1;
      if found and exists(select 1 from jsonb_array_elements(rows) current_check
        where claim.check_ids ? (current_check->>'id')
          and current_check->'bankMatch'->>'transactionId'=claim.transaction_id::text
          and current_check->'bankMatch'->>'phase'='deposited'
          and not (current_check->'bankMatch' ? 'warning')
          and coalesce(current_check->>'bankAutomationDisabled','false')<>'true'
          and netunim_internal.check_bank_number(current_check->>'checkNumber')=legacy_number
          and netunim_internal.check_bank_money(current_check->>'amount')=abs(tx.amount)) then
        -- Legacy amount/date inference created a durable claim before this bank
        -- presentation was understood. Remove only that exact single-member claim
        -- and mark its current evidence provisional so the stronger rule can replace it.
        delete from netunim_internal.check_bank_claims l where l.owner_id=claim.owner_id and l.transaction_id=claim.transaction_id;
        legacy_item:=jsonb_build_object('checkNumber',legacy_number,'bankNumber','','branchNumber','','accountNumber','','amount',abs(tx.amount));
        select coalesce(jsonb_agg(case when claim.check_ids ? (current_check->>'id')
          and current_check->'bankMatch'->>'transactionId'=claim.transaction_id::text
          and netunim_internal.check_bank_number(current_check->>'checkNumber')=legacy_number
          and netunim_internal.check_bank_money(current_check->>'amount')=abs(tx.amount)
          then current_check||jsonb_build_object('bankMatch',((current_check->'bankMatch')-'autoConfirmed')||jsonb_build_object(
            'provisionalReference',true,'provisional',true,'bankReference',tx.bank_reference,
            'bankItem',legacy_item,'matchMethod','number')) else current_check end order by ord),'[]') into rows
          from jsonb_array_elements(rows) with ordinality a(current_check,ord);
      end if;
    end if;
  end loop;

  -- Reserve reduced successors BEFORE proposing fresh deposits, so a replacement
  -- cannot consume unrelated open checks and leave its original group stranded.
  for claim in select l.* from netunim_internal.check_bank_claims l where l.owner_id=new.owner_id
    and l.account_key=new.account_key and l.account_role=new.account_role and not l.conflicted
  loop
    select * into tx from public.bank_transactions where id=claim.transaction_id and owner_id=new.owner_id;
    pack:=netunim_internal.check_bank_items(tx);
    if claim.bank_members is null and tx.amount=(claim.source_transaction->>'amount')::numeric
      and tx.last_seen_at=new.snapshot_at and tx.presence_state='present' and pack->>'kind'='valid'
      and not exists(select 1 from jsonb_array_elements(claim.members) member where not exists(
        select 1 from jsonb_array_elements(pack->'items') i where netunim_internal.check_bank_item_matches(coalesce(nullif(member->'bankItem','null'::jsonb),member),i))) then
      update netunim_internal.check_bank_claims set bank_members=pack->'items' where owner_id=claim.owner_id and transaction_id=claim.transaction_id;
      claim.bank_members:=pack->'items';
    end if;
    remainder:=netunim_internal.check_bank_remainder(claim,new);
    if remainder->>'kind'='reduced' and (remainder->>'transactionId')::bigint<>claim.transaction_id then
      perform netunim_internal.move_check_bank_claim(claim.transaction_id,(remainder->>'transactionId')::bigint);
    end if;
    if remainder is not null then
      batches:=batches||jsonb_build_object(claim.transaction_id::text,remainder,(remainder->>'transactionId'),remainder);
    end if;
  end loop;

  -- Proposals are built against the SAME original check list before accepting any of them.
  for tx in select b.* from public.bank_transactions b
    where b.owner_id=new.owner_id and b.account_key=new.account_key and b.account_role=new.account_role
      and b.amount>0 and b.currency='ILS' and b.status in ('pending','completed')
      and b.presence_state='present' and b.last_seen_at=new.snapshot_at
      and (
        ((b.transaction_date at time zone 'Asia/Jerusalem')::date between new.coverage_from and least(new.coverage_to,(new.snapshot_at at time zone 'Asia/Jerusalem')::date)
          and b.transaction_date>=new.snapshot_at-interval '30 days')
        -- A pending direct cheque deposit can be visible TODAY while Hapoalim gives
        -- it the future value/event date. It is current evidence because this exact
        -- row was observed in the fenced snapshot, not because its future date is trusted.
        or netunim_internal.check_bank_pending_reference_number(b)<>''
      )
      and netunim_internal.check_bank_kind(b.description) in ('deposit','redeposit')
    order by b.id
  loop
    proposals:=proposals||netunim_internal.check_bank_proposals(rows,tx);
  end loop;
  for proposal in select value from jsonb_array_elements(proposals) loop
    select * into tx from public.bank_transactions where id=(proposal->>'transactionId')::bigint;
    ids:=proposal->'ids';
    provisional_reference:=coalesce((proposal->>'provisionalReference')::boolean,false);
    -- If the same snapshot already contains a completed structured bank item for
    -- this check, never let the weaker pending-reference proposal compete with it.
    if provisional_reference and exists(select 1 from jsonb_array_elements(proposals) stronger
      where not coalesce((stronger->>'provisionalReference')::boolean,false)
        and stronger->>'kind'='unique' and stronger ? 'bankItem'
        and exists(select 1 from jsonb_array_elements(stronger->'candidates') sc where ids ? (sc->>'id'))) then
      continue;
    end if;
    select * into claim from netunim_internal.check_bank_claims where owner_id=new.owner_id and transaction_id=tx.id;
    already_claimed:=found;
    if already_claimed and proposal->>'kind'='unique' and not exists(select 1 from jsonb_array_elements_text(ids) id where not (claim.check_ids ? id)) then continue; end if;
    if already_claimed and proposal ? 'bankItem' and (
      exists(select 1 from jsonb_array_elements(claim.members) member where
        netunim_internal.check_bank_same_item(coalesce(nullif(member->'bankItem','null'::jsonb),member),proposal->'bankItem'))
      or (select sum((member->>'amount')::numeric) from jsonb_array_elements(claim.members) member)=(claim.source_transaction->>'amount')::numeric
    ) then continue; end if;
    -- An amount-only claim reserves the entire movement, including deleted checks.
    if already_claimed and not (proposal ? 'bankItem') then continue; end if;
    -- Every alternative (including an ambiguous/over-limit deposit) blocks shared candidates.
    select count(*) into overlapcount from jsonb_array_elements(proposals) p
    where (p->>'transactionId',p->>'slot') is distinct from (proposal->>'transactionId',proposal->>'slot')
      and not (not provisional_reference and proposal ? 'bankItem'
        and coalesce((p->>'provisionalReference')::boolean,false))
      and exists(select 1 from jsonb_array_elements(p->'candidates') x where ids ? (x->>'id'));
    phase:=case when proposal->>'kind'='unique' and overlapcount=0 then 'deposited' else 'ambiguous' end;
    if phase='deposited' and exists(select 1 from jsonb_array_elements(rows) x where ids ? (x->>'id')
      and (x->>'status'='נפרע' or x->'bankMatch'->>'phase' in ('deposited','cleared','missing'))
      and not (coalesce((x->'bankMatch'->>'provisionalReference')::boolean,false)
        and proposal ? 'bankItem' and netunim_internal.check_bank_same_item(x,proposal->'bankItem'))) then phase:='ambiguous'; end if;
    if phase='deposited' and netunim_internal.check_bank_kind(tx.description)='redeposit' and exists(
      select 1 from jsonb_array_elements(rows) x where ids ? (x->>'id') and (
        not (proposal ? 'bankItem') or netunim_internal.check_bank_number(x->>'checkNumber')=''
        or not netunim_internal.check_bank_same_item(coalesce(nullif(x->'bankMatch'->'bankItem','null'::jsonb),x),proposal->'bankItem')
        or exists(select 1 from public.bank_transactions r where r.owner_id=new.owner_id and r.account_key=new.account_key and r.account_role=new.account_role
          and r.amount<0 and r.presence_state='present' and netunim_internal.check_bank_kind(r.description)='return'
          and r.transaction_date::date=tx.transaction_date::date and netunim_internal.check_bank_return_matches(x,jsonb_build_object('bankItem',proposal->'bankItem'),r))
        or (x->>'status'='חזר' and exists(select 1 from public.bank_transactions r where r.owner_id=new.owner_id
          and r.id=(x->'bankMatch'->>'returnTransactionId')::bigint and r.transaction_date::date>=tx.transaction_date::date)))) then
      phase:='ambiguous';proposal:=proposal||jsonb_build_object('warning','redeposit_unverified'); end if;
    if phase='deposited' and not provisional_reference then
      select jsonb_agg(jsonb_build_object('id',member->>'id','name',member->>'name','amount',member->'amount','dueDate',member->>'dueDate',
        'account',coalesce(member->>'account','עסקי'),'status','בקופה','checkNumber',member->>'checkNumber','bankItem',proposal->'bankItem')) into members
      from jsonb_array_elements(rows) member where ids ? (member->>'id');
      insert into netunim_internal.check_bank_claims(owner_id,document_name,transaction_id,account_key,account_role,check_ids,members,source_transaction,bank_members)
      values(new.owner_id,'main',tx.id,new.account_key,new.account_role,ids,members,to_jsonb(tx),
        case when netunim_internal.check_bank_items(tx)->>'kind'='valid' then netunim_internal.check_bank_items(tx)->'items' end)
      on conflict(owner_id,transaction_id) do update set
        check_ids=netunim_internal.check_bank_claims.check_ids||excluded.check_ids,
        members=netunim_internal.check_bank_claims.members||excluded.members;
    elsif phase<>'deposited' then
      select jsonb_agg(x->>'id') into ids from jsonb_array_elements(proposal->'candidates') x;
    end if;
    nextrows:='[]';
    for c in select value from jsonb_array_elements(rows) loop
      if ids ? (c->>'id') and c->>'status' in ('בקופה','הופקד - במעקב','חזר')
        and (coalesce(c->'bankMatch'->>'phase','') not in ('deposited','cleared','missing')
          or (coalesce((c->'bankMatch'->>'provisionalReference')::boolean,false)
            and proposal ? 'bankItem' and netunim_internal.check_bank_same_item(c,proposal->'bankItem'))) then
        replacing_provisional_reference:=coalesce((c->'bankMatch'->>'provisionalReference')::boolean,false);
        event:=tx.id::text||':'||phase||case when phase='ambiguous' then ':'||md5(ids::text) else '' end;
        m:=jsonb_build_object('transactionId',tx.id,'accountKey',tx.account_key,'accountRole',tx.account_role,'phase',phase,'eventId',event,
          'bankItem',proposal->'bankItem','provisional',tx.status='pending',
          'matchMethod',case when proposal ? 'bankItem' and netunim_internal.check_bank_number(c->>'checkNumber')<>''
            and netunim_internal.check_bank_number(c->>'checkNumber')=proposal->'bankItem'->>'checkNumber' then 'number' else 'amount' end,
          'description',tx.description,'amount',tx.amount,'date',case when provisional_reference then (new.snapshot_at at time zone 'Asia/Jerusalem')::date else (tx.transaction_date at time zone 'Asia/Jerusalem')::date end,
          'detectedAt',case when c->'bankMatch'->>'eventId'=event then c->'bankMatch'->'detectedAt' else to_jsonb(new.snapshot_at) end,
          'completedSeenDate',case when tx.status='completed' and phase='deposited' then (new.snapshot_at at time zone 'Asia/Jerusalem')::date end,
          'checkIds',ids,
          'previousStatus',case when replacing_provisional_reference then coalesce(c->'bankMatch'->>'previousStatus',c->>'status') else c->>'status' end,
          'previousDepositDate',case when replacing_provisional_reference then c->'bankMatch'->'previousDepositDate' else c->'depositDate' end);
        if proposal ? 'warning' then m:=m||jsonb_build_object('warning',proposal->>'warning'); end if;
        if provisional_reference then m:=m||jsonb_build_object('provisionalReference',true,'bankReference',tx.bank_reference); end if;
        c:=c||jsonb_build_object('bankMatch',m);
        if phase='deposited' then c:=c||jsonb_build_object('status','הופקד - במעקב',
          'depositDate',case when replacing_provisional_reference then coalesce(c->>'depositDate',m->>'date') else m->>'date' end,
          'clearedDate',null); end if;
      end if;
      nextrows:=nextrows||jsonb_build_array(c);
    end loop;
    rows:=nextrows;
  end loop;

  -- Linked checks keep their claim even after rejection, deletion or manual correction.
  nextrows:='[]';
  for c in select value from jsonb_array_elements(rows) loop
    m:=c->'bankMatch'; phase:=m->>'phase';
    remainder:=batches->(m->>'transactionId');reduced_survivor:=false;
    if phase in ('deposited','cleared','missing') and coalesce(c->>'bankAutomationDisabled','false')<>'true'
      and m->>'accountKey'=new.account_key
      and coalesce(c->>'account','עסקי')=(case new.account_role when 'home' then 'ביתי' else 'עסקי' end) then
      select * into claim from netunim_internal.check_bank_claims where owner_id=new.owner_id
        and (transaction_id=(m->>'transactionId')::bigint or previous_transaction_ids ? (m->>'transactionId'));
      select * into tx from public.bank_transactions where owner_id=new.owner_id and id=coalesce(claim.transaction_id,(m->>'transactionId')::bigint) and account_role=new.account_role;
      if found then
        m:=m||jsonb_build_object('transactionId',tx.id);
        if claim.check_ids is not null and not (m ? 'remainder') then m:=m||jsonb_build_object('checkIds',claim.check_ids); end if;
        pack:=netunim_internal.check_bank_items(tx);
        if pack->>'kind'='valid' and tx.presence_state='present' and tx.last_seen_at=new.snapshot_at and (m->'bankItem' is null or m->'bankItem'='null'::jsonb) then
          select count(*),jsonb_agg(i)->0 into mapped_count,mapped_item from jsonb_array_elements(pack->'items') i where netunim_internal.check_bank_item_matches(c,i)
            and exists(select 1 from jsonb_array_elements(netunim_internal.check_bank_claim_members(claim)) member
              where member->>'id'=c->>'id' and netunim_internal.check_bank_same_item(member,i));
          if mapped_count=1 then m:=m||jsonb_build_object('bankItem',mapped_item,'matchMethod',case when netunim_internal.check_bank_number(c->>'checkNumber')=mapped_item->>'checkNumber' then 'number' else 'amount' end); end if;
        end if;
        if tx.status='completed' then m:=m||jsonb_build_object('provisional',false); end if;
        if remainder is null and m ? 'remainder' then
          m:=m-'remainder';
          if m->>'warning' in ('batch_missing','batch_ambiguous') then m:=m-'warning'; end if;
        end if;
        if remainder->>'kind'='full' and m ? 'remainder' then
          m:=(m-'remainder')||jsonb_build_object('amount',remainder->'originalAmount','checkIds',remainder->'originalIds');
        end if;
        if remainder->>'kind'='reduced' then
          reduced_survivor:=remainder->'remainingIds' ? (c->>'id');
          m:=m||jsonb_build_object('remainder',remainder);
          if reduced_survivor then
            -- Verify future amount/number/count against the surviving subset, while
            -- immutable original membership stays available in the claim forever.
            m:=m||jsonb_build_object('amount',tx.amount,'checkIds',remainder->'remainingIds');
          end if;
        end if;
        number_confirmed:=netunim_internal.check_bank_number_confirmed(c,m,tx,rows);
        if number_confirmed then m:=m||jsonb_build_object('matchMethod','number'); end if;
        txday:=greatest((tx.transaction_date at time zone 'Asia/Jerusalem')::date,(tx.processed_date at time zone 'Asia/Jerusalem')::date);
        -- Amount-only returns are alerts and block clearing, but do not prove WHICH cheque returned.
        returncount:=0;
        for ret in select r.* from public.bank_transactions r where r.owner_id=new.owner_id
          and r.account_key=new.account_key and r.account_role=new.account_role and r.amount<0
          and r.currency='ILS' and r.presence_state<>'missing'
          and netunim_internal.check_bank_kind(r.description)='return'
          and (r.transaction_date at time zone 'Asia/Jerusalem')::date>=txday
          and (r.transaction_date at time zone 'Asia/Jerusalem')::date<=txday+30
          and (r.transaction_date at time zone 'Asia/Jerusalem')::date<=(new.snapshot_at at time zone 'Asia/Jerusalem')::date
        loop
          ret.amount:=-ret.amount;
          if netunim_internal.check_bank_candidates(netunim_internal.check_bank_claim_members(claim),ret)->>'kind'<>'none' then
            returncount:=returncount+1;
          end if;
        end loop;
        if reduced_survivor and remainder->>'evidence'='return_debits' then returncount:=0; end if;
        select r.* into ret from public.bank_transactions r where r.owner_id=new.owner_id
          and r.account_key=new.account_key and r.account_role=new.account_role and r.amount<0
          and r.status='completed' and r.currency='ILS' and r.presence_state='present'
          and netunim_internal.check_bank_kind(r.description)='return'
          and (r.transaction_date at time zone 'Asia/Jerusalem')::date>=txday
          and (r.transaction_date at time zone 'Asia/Jerusalem')::date<=(new.snapshot_at at time zone 'Asia/Jerusalem')::date
          and netunim_internal.check_bank_return_matches(c,m,r)
          and (select count(*) from jsonb_array_elements(rows) x where coalesce(x->>'account','עסקי')=coalesce(c->>'account','עסקי')
            and netunim_internal.check_bank_same_item(coalesce(nullif(x->'bankMatch'->'bankItem','null'::jsonb),x),coalesce(nullif(m->'bankItem','null'::jsonb),c)))=1
          order by r.id limit 1;
        if claim.conflicted then
          phase:='missing';m:=m||jsonb_build_object('warning','identity_conflict');
          c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null);
        elsif found then
          phase:='returned'; c:=c||jsonb_build_object('status','חזר','clearedDate',null);
          m:=(m-'warning')||jsonb_build_object('returnTransactionId',ret.id,'returnDate',(ret.transaction_date at time zone 'Asia/Jerusalem')::date,'reason',concat_ws(' · ',nullif(ret.message_headline,''),nullif(ret.message_detail,''),ret.description));
        elsif remainder->>'kind'='reduced' and not reduced_survivor then
          phase:='missing';m:=m||jsonb_build_object('warning','batch_missing');
          c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null);
        elsif remainder->>'kind'='ambiguous' then
          phase:='missing';m:=m||jsonb_build_object('warning','batch_ambiguous','remainder',remainder);
          c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null);
        elsif reduced_survivor and c->'bankMatch'->'remainder' is distinct from remainder then
          phase:='deposited';m:=(m-'warning')||jsonb_build_object('completedSeenDate',case when tx.status='completed' then (new.snapshot_at at time zone 'Asia/Jerusalem')::date end);
          c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null);
        elsif tx.presence_state='missing' then
          phase:='missing';
          -- A removed credit revokes an automatic cleared state; never assert a return without evidence.
          if c->>'status'='נפרע' then c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null); end if;
        elsif returncount>0 then
          m:=m||jsonb_build_object('warning','possible_return');
          if c->>'status'='נפרע' then phase:='deposited';c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null); end if;
        elsif pack->>'kind'='none' and m->'bankItem' is not null and m->'bankItem'<>'null'::jsonb
          and not (tx.status='pending' and coalesce((m->>'provisionalReference')::boolean,false)) then
          m:=m||jsonb_build_object('warning','details_unavailable');
          if c->>'status'='נפרע' then phase:='deposited';c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null); end if;
        elsif tx.amount<>(m->>'amount')::numeric or tx.currency<>'ILS' or tx.status not in ('pending','completed')
          or coalesce(netunim_internal.check_bank_kind(tx.description),'') not in ('deposit','redeposit')
          or pack->>'kind'='invalid'
          or (pack->>'kind'='valid' and not exists(select 1 from jsonb_array_elements(pack->'items') i
            where netunim_internal.check_bank_item_matches(coalesce(nullif(m->'bankItem','null'::jsonb),c),i)))
          or (pack->>'kind'='valid' and m->'bankItem' is not null and m->'bankItem'<>'null'::jsonb and not exists(
            select 1 from jsonb_array_elements(pack->'items') i where netunim_internal.check_bank_same_item(m->'bankItem',i)))
          or (pack->>'kind'='none' and netunim_internal.check_bank_number(c->>'checkNumber')<>''
            and jsonb_typeof(tx.check_details->'checkNumbers')='array' and tx.check_details->'checkNumbers'<>'[]'::jsonb
            and not exists(select 1 from jsonb_array_elements_text(tx.check_details->'checkNumbers') n where netunim_internal.check_bank_number(n)=netunim_internal.check_bank_number(c->>'checkNumber')))
          or (pack->>'kind'<>'valid' and coalesce(remainder->>'evidence','')<>'return_debits' and coalesce(tx.check_details->>'checkCount','') ~ '^[1-9][0-9]*$'
            and (tx.check_details->>'checkCount')::numeric<>jsonb_array_length(m->'checkIds')) then
          phase:='missing';m:=m||jsonb_build_object('warning','changed');
          c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null);
        elsif tx.last_seen_at=new.snapshot_at and pack->>'kind'='valid'
          and netunim_internal.check_bank_number(c->>'checkNumber')<>'' and not number_confirmed then
          phase:='deposited';m:=m||jsonb_build_object('warning','number_ambiguous');
          c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null);
        elsif phase='missing' and tx.presence_state='present' and tx.last_seen_at=new.snapshot_at then
          phase:='deposited';m:=m-'warning';
        elsif tx.status='completed' and tx.presence_state='present' and tx.last_seen_at=new.snapshot_at then
          if m->>'completedSeenDate' is null then m:=m||jsonb_build_object('completedSeenDate',(new.snapshot_at at time zone 'Asia/Jerusalem')::date); end if;
          clearafter:=netunim_internal.check_bank_clear_after(greatest(txday,(m->>'completedSeenDate')::date));
          m:=m||jsonb_build_object('clearAfter',clearafter);
          if clearafter is null then m:=m||jsonb_build_object('warning','calendar');
          elsif m->>'warning' in ('calendar','possible_return','details_unavailable','number_ambiguous') then m:=m-'warning'; end if;
          if clearafter is not null and (new.snapshot_at at time zone 'Asia/Jerusalem')::date>=clearafter
            and new.coverage_from<=txday and new.coverage_to>=(new.snapshot_at at time zone 'Asia/Jerusalem')::date
            and (number_confirmed or c->>'bankReview'=m->>'eventId') and not (c->'bankMatch' ? 'warning')
            and m->'bankItem' is not distinct from c->'bankMatch'->'bankItem' and coalesce((c->'bankMatch'->>'provisional')::boolean,false)=false
            and phase='deposited' then
            phase:='cleared';c:=c||jsonb_build_object('status','נפרע','clearedDate',(new.snapshot_at at time zone 'Asia/Jerusalem')::date);
          end if;
        end if;
        if tx.last_seen_at=new.snapshot_at then
          m:=m||jsonb_build_object('autoConfirmed',number_confirmed and phase in ('deposited','cleared') and not (m ? 'warning'));
        elsif phase not in ('deposited','cleared') or m ? 'warning' then m:=m-'autoConfirmed'; end if;
        event:=m->>'eventId';
        if coalesce((m->>'autoConfirmed')::boolean,false) is distinct from coalesce((c->'bankMatch'->>'autoConfirmed')::boolean,false) or phase is distinct from c->'bankMatch'->>'phase' or m->>'warning' is distinct from c->'bankMatch'->>'warning'
          or m->'remainder' is distinct from c->'bankMatch'->'remainder'
          or m->'bankItem' is distinct from c->'bankMatch'->'bankItem' or m->'provisional' is distinct from c->'bankMatch'->'provisional'
          or m->'provisionalReference' is distinct from c->'bankMatch'->'provisionalReference' then
          event:=tx.id::text||':'||phase||':'||new.snapshot_at::text;
        end if;
        c:=c||jsonb_build_object('bankMatch',m||jsonb_build_object('phase',phase,'eventId',event));
      else
        c:=c||jsonb_build_object('status','הופקד - במעקב','clearedDate',null,'bankMatch',(m-'autoConfirmed')||jsonb_build_object('phase','missing','eventId',(m->>'transactionId')||':missing'));
      end if;
    end if;
    nextrows:=nextrows||jsonb_build_array(c);
  end loop;
  rows:=nextrows;nextrows:='[]';
  for c in select value from jsonb_array_elements(rows) loop
    if coalesce(c->>'bankAutomationDisabled','false')<>'true'
      and coalesce(c->'bankMatch'->>'phase','') in ('','overdue','unverified')
      and coalesce(c->>'account','עסקי')=(case new.account_role when 'home' then 'ביתי' else 'עסקי' end)
      and c->>'status' in ('בקופה','הופקד - במעקב')
      and netunim_internal.check_bank_date(c->>'dueDate') between new.coverage_from and (new.snapshot_at at time zone 'Asia/Jerusalem')::date
      and new.coverage_to>=(new.snapshot_at at time zone 'Asia/Jerusalem')::date then
      phase:=case c->>'status' when 'בקופה' then 'overdue' else 'unverified' end;
      event:='no-bank:'||new.account_key||':'||(c->>'id')||':'||(c->>'dueDate')||':'||phase;
      if c->'bankMatch'->>'eventId' is distinct from event then
        c:=c||jsonb_build_object('bankMatch',jsonb_build_object('phase',phase,'eventId',event,'accountKey',new.account_key,
          'observedDate',(new.snapshot_at at time zone 'Asia/Jerusalem')::date,'date',c->>'dueDate'));
      end if;
    end if;
    nextrows:=nextrows||jsonb_build_array(c);
  end loop;
  select coalesce(jsonb_agg(netunim_internal.check_bank_record_history(a.c,new.snapshot_at) order by a.ord),'[]')
    into nextrows from jsonb_array_elements(nextrows) with ordinality a(c,ord);
  if nextrows is distinct from doc.state->'checks' then
    perform set_config('app.check_bank_reconcile','1',true);
    perform netunim_internal.save_shared_checks_document('main',doc.revision,jsonb_build_object('checks',nextrows));
    perform set_config('app.check_bank_reconcile','0',true);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.save_bank_sync_snapshot(p_document_name text, p_bank_state jsonb, p_snapshot_token text, p_snapshot_seq bigint)
 RETURNS TABLE(finance_revision bigint, kupa_revision bigint, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal', 'extensions'
AS $function$
declare
  v_owner uuid := auth.uid();
  v_kupa_state jsonb;
  v_kupa_bank jsonb;
  v_old_snapshot_seq bigint := 0;
  v_shared_max_seq bigint := 0;
  v_finance_state jsonb;
  v_finance_revision bigint;
  v_kupa_revision bigint;
  v_finance_updated_at timestamptz;
  v_kupa_updated_at timestamptz;
  v_operation_seq bigint;
  v_operation_hash text;
  v_payload_hash text;
  v_now timestamptz := clock_timestamp();
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('netunim_financial_write:' || v_owner::text, 0)) then
    raise exception 'save_busy' using errcode='PT429', hint='Another financial save is already in progress. Retry later.';
  end if;
  perform set_config('lock_timeout', '100ms', true);
  if p_document_name is null or btrim(p_document_name)='' then raise exception 'invalid_document_name' using errcode='22023'; end if;
  if p_bank_state is null or jsonb_typeof(p_bank_state) is distinct from 'object' then raise exception 'invalid_bank_sync_state' using errcode='22023'; end if;
  if coalesce(btrim(p_snapshot_token),'')='' or length(p_snapshot_token)>200 then raise exception 'invalid_bank_snapshot_token' using errcode='22023'; end if;
  if p_snapshot_seq is null or p_snapshot_seq<0 then raise exception 'invalid_bank_snapshot_sequence' using errcode='22023'; end if;
  v_payload_hash:=encode(digest(convert_to(p_bank_state::text, 'UTF8'), 'sha256'), 'hex');

  -- Canonical order remains Kupa then Finance; the shared financial advisory gate is unchanged.
  select d.state,d.revision,d.updated_at into v_kupa_state,v_kupa_revision,v_kupa_updated_at
  from public.kupa_documents d
  where d.owner_id=v_owner and d.document_name=p_document_name
  for update;
  if v_kupa_state is null then raise exception 'kupa_document_not_found' using errcode='P0002'; end if;

  select f.state,f.revision,f.updated_at into v_finance_state,v_finance_revision,v_finance_updated_at
  from public.finance_sync_documents f
  where f.owner_id=v_owner and f.document_name=p_document_name
  for update;

  select o.snapshot_seq,o.payload_sha256 into v_operation_seq,v_operation_hash
  from netunim_internal.bank_sync_operations o
  where o.owner_id=v_owner and o.document_name=p_document_name and o.operation_id=p_snapshot_token;
  if found then
    if v_operation_seq<>p_snapshot_seq or v_operation_hash<>v_payload_hash then
      raise exception 'idempotency_key_reuse' using errcode='PT422', hint='A bank snapshot token cannot be reused with a different payload.';
    end if;
    if v_finance_revision is null then raise exception 'finance_document_not_found' using errcode='P0002'; end if;
    finance_revision:=v_finance_revision;
    kupa_revision:=v_kupa_revision;
    updated_at:=greatest(v_finance_updated_at,v_kupa_updated_at);
    return next; return;
  end if;

  v_kupa_bank:=coalesce(v_kupa_state->'bank','{}'::jsonb);
  if jsonb_typeof(v_kupa_bank->'snapshotSeq')='number' then
    begin v_old_snapshot_seq:=greatest(0,(v_kupa_bank->>'snapshotSeq')::bigint);
    exception when others then raise exception 'invalid_existing_bank_snapshot_sequence' using errcode='22023'; end;
  end if;

  select coalesce(max((e.value->>'seq')::bigint),0) into v_shared_max_seq
  from public.shared_checks_documents s
  left join lateral jsonb_array_elements(case when jsonb_typeof(s.state->'bankEvents')='array' then s.state->'bankEvents' else '[]'::jsonb end) e(value) on true
  where s.owner_id=v_owner and s.document_name='main';
  v_shared_max_seq:=coalesce(v_shared_max_seq,0);
  if p_snapshot_seq<v_old_snapshot_seq then
    raise exception 'stale_bank_snapshot_watermark' using errcode='40001',hint='Refresh shared checks before saving the bank snapshot.';
  end if;
  if p_snapshot_seq>greatest(v_old_snapshot_seq,v_shared_max_seq) then
    raise exception 'bank_snapshot_watermark_ahead_of_server' using errcode='22023',hint='The requested watermark was not observed in shared check events.';
  end if;

  if v_finance_revision is null then
    insert into public.finance_sync_documents(owner_id,document_name,revision,state,updated_at)
    values(v_owner,p_document_name,1,jsonb_build_object('bank',p_bank_state,'creditSync',null),v_now)
    returning revision into v_finance_revision;
  else
    v_finance_state:=coalesce(v_finance_state,'{}'::jsonb);
    update public.finance_sync_documents f
    set revision=f.revision+1,state=jsonb_set(v_finance_state,'{bank}',p_bank_state,true),updated_at=v_now
    where f.owner_id=v_owner and f.document_name=p_document_name
    returning f.revision into v_finance_revision;
  end if;

  perform set_config('app.kupa_rpc_write','1',true);
  v_kupa_bank:=jsonb_build_object(
    'currentBalance',null,'updatedAt',null,'asOfDate',null,
    'adjustments',coalesce(v_kupa_bank->'adjustments','[]'::jsonb),
    'source',null,'sourceAccount',null,
    'snapshotToken',p_snapshot_token,'snapshotSeq',p_snapshot_seq
  );
  v_kupa_state:=(v_kupa_state-'bank'-'creditSync')||jsonb_build_object('bank',v_kupa_bank);
  update public.kupa_documents d
  set revision=d.revision+1,state=v_kupa_state,updated_at=v_now
  where d.owner_id=v_owner and d.document_name=p_document_name
  returning d.revision into v_kupa_revision;

  insert into netunim_internal.bank_sync_operations(owner_id,document_name,operation_id,snapshot_seq,payload_sha256,created_at)
  values(v_owner,p_document_name,p_snapshot_token,p_snapshot_seq,v_payload_hash,v_now);
  finance_revision:=v_finance_revision;kupa_revision:=v_kupa_revision;updated_at:=v_now;return next;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.save_finance_sync_document(p_document_name text, p_expected_revision bigint, p_state jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare
  v_owner uuid := auth.uid();
  v_current bigint;
  v_current_updated_at timestamptz;
  v_current_state jsonb;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('netunim_financial_write:' || v_owner::text, 0)) then
    raise exception 'save_busy' using errcode='PT429', hint='Another financial save is already in progress. Retry later.';
  end if;
  perform set_config('lock_timeout', '100ms', true);
  if p_document_name is null or btrim(p_document_name)='' then raise exception 'invalid_document_name' using errcode='22023'; end if;
  if p_expected_revision is null or p_expected_revision < 0 then raise exception 'invalid_expected_revision' using errcode='22023'; end if;
  if p_state is null or jsonb_typeof(p_state) is distinct from 'object' then raise exception 'invalid_finance_sync_state' using errcode='22023'; end if;

  select d.revision, d.updated_at, d.state
  into v_current, v_current_updated_at, v_current_state
  from public.finance_sync_documents d
  where d.owner_id=v_owner and d.document_name=p_document_name
  for update;

  if v_current is null then
    if p_expected_revision<>0 then raise exception 'revision_conflict' using errcode='PT409'; end if;
    insert into public.finance_sync_documents(owner_id,document_name,revision,state,updated_at)
    values(v_owner,p_document_name,1,p_state,now())
    returning finance_sync_documents.revision,finance_sync_documents.updated_at,finance_sync_documents.state
    into revision,updated_at,state;
    return next; return;
  end if;

  -- Lost ACK replay: equality is checked before optimistic revision conflict.
  if v_current_state = p_state then
    revision:=v_current; updated_at:=v_current_updated_at; state:=v_current_state;
    return next; return;
  end if;
  if v_current<>p_expected_revision then raise exception 'revision_conflict' using errcode='PT409'; end if;

  update public.finance_sync_documents d
  set revision=d.revision+1,state=p_state,updated_at=now()
  where d.owner_id=v_owner and d.document_name=p_document_name
  returning d.revision,d.updated_at,d.state into revision,updated_at,state;
  return next;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.save_finance_sync_document_current(p_document_name text, p_expected_revision bigint, p_state jsonb, p_operation_id text)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal', 'extensions'
AS $function$
declare
  v_owner uuid:=auth.uid();v_payload_hash text;v_ledger_hash text;v_applied_revision bigint;
  v_saved_revision bigint;v_saved_updated_at timestamptz;v_saved_state jsonb;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if p_document_name is null or btrim(p_document_name)='' then raise exception 'invalid_document_name' using errcode='22023'; end if;
  if p_expected_revision is null or p_expected_revision<0 then raise exception 'invalid_expected_revision' using errcode='22023'; end if;
  if p_state is null or jsonb_typeof(p_state) is distinct from 'object' then raise exception 'invalid_finance_sync_state' using errcode='22023'; end if;
  if coalesce(btrim(p_operation_id),'')='' or length(p_operation_id)>200 then raise exception 'invalid_operation_id' using errcode='22023'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('netunim_financial_write:'||v_owner::text,0)) then
    raise exception 'save_busy' using errcode='PT429',hint='Another financial save is already in progress. Retry later.';
  end if;
  perform set_config('lock_timeout','100ms',true);
  v_payload_hash:=encode(extensions.digest(convert_to(p_state::text,'UTF8'),'sha256'),'hex');
  select o.payload_sha256,o.applied_revision into v_ledger_hash,v_applied_revision
  from netunim_internal.document_sync_operations o
  where o.owner_id=v_owner and o.domain='finance' and o.document_name=p_document_name and o.operation_id=p_operation_id;
  if found then
    if v_ledger_hash<>v_payload_hash then raise exception 'idempotency_key_reuse' using errcode='PT422',hint='An operation id cannot be reused with a different payload.'; end if;
    select d.revision,d.updated_at,d.state into revision,updated_at,state from public.finance_sync_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
    if revision is null then raise exception 'operation_replay_document_missing' using errcode='P0002'; end if;
    operation_replayed:=true;operation_revision:=v_applied_revision;return next;return;
  end if;
  begin
    select x.revision,x.updated_at,x.state into v_saved_revision,v_saved_updated_at,v_saved_state
    from netunim_internal.save_finance_sync_document(p_document_name,p_expected_revision,p_state) x;
  exception when lock_not_available then raise exception 'save_busy' using errcode='PT429',hint='A financial row is temporarily locked. Retry later.'; end;
  if v_saved_revision is null then raise exception 'save_result_missing' using errcode='P0002'; end if;
  insert into netunim_internal.document_sync_operations(owner_id,domain,document_name,operation_id,payload_sha256,applied_revision,created_at)
  values(v_owner,'finance',p_document_name,p_operation_id,v_payload_hash,v_saved_revision,coalesce(v_saved_updated_at,now()));
  select d.revision,d.updated_at,d.state into revision,updated_at,state from public.finance_sync_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
  operation_replayed:=false;operation_revision:=v_saved_revision;return next;
end $function$

CREATE OR REPLACE FUNCTION netunim_internal.save_kupa_document(p_document_name text, p_expected_revision bigint, p_state jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_owner uuid := auth.uid();
  v_current_revision bigint;
  v_old_state jsonb;
  v_old_updated_at timestamptz;
  v_server_state jsonb;
  v_bank jsonb;
  v_old_bank jsonb;
  v_new_token text;
  v_old_token text;
  v_requested_snapshot_num numeric;
  v_requested_snapshot_seq bigint;
  v_old_snapshot_seq bigint := 0;
  v_shared_max_seq bigint := 0;
  v_now timestamptz;
  v_new_revision bigint;
  v_new_updated_at timestamptz;
begin
  if v_owner is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  if p_document_name is null or btrim(p_document_name) = '' then
    raise exception 'invalid_document_name' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'invalid_expected_revision' using errcode = '22023';
  end if;
  if p_state is null
     or jsonb_typeof(p_state) is distinct from 'object'
     or (p_state ? 'checks')
     or jsonb_typeof(p_state->'credits') is distinct from 'array'
     or jsonb_typeof(p_state->'cash') is distinct from 'array'
     or jsonb_typeof(p_state->'expenses') is distinct from 'array'
     or jsonb_typeof(p_state->'cards') is distinct from 'array'
     or jsonb_typeof(p_state->'bank') is distinct from 'object'
     or jsonb_typeof(p_state#>'{bank,adjustments}') is distinct from 'array' then
    raise exception 'invalid_kupa_state'
      using errcode = '22023',
            hint = 'Post-cutover state must contain credits/cash/expenses/cards arrays and bank object, without checks.';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_state#>'{bank,adjustments}') a
    where a->>'type' = 'check_deposit'
  ) then
    raise exception 'legacy_check_deposit_forbidden'
      using errcode = '22023', hint = 'Check deposits are derived from shared_checks_documents after cutover.';
  end if;

  perform set_config('app.kupa_rpc_write', '1', true);

  select d.revision, d.state, d.updated_at
    into v_current_revision, v_old_state, v_old_updated_at
  from public.kupa_documents d
  where d.owner_id = v_owner and d.document_name = p_document_name
  for update;

  v_server_state := p_state;
  v_bank := p_state->'bank';
  v_old_bank := coalesce(v_old_state->'bank','{}'::jsonb);
  v_new_token := nullif(v_bank->>'snapshotToken','');
  v_old_token := nullif(v_old_bank->>'snapshotToken','');

  if v_new_token is distinct from v_old_token and v_new_token is not null then
    if jsonb_typeof(v_bank->'snapshotSeq') is distinct from 'number'
       or (v_bank->>'source' = 'manual' and jsonb_typeof(v_bank->'currentBalance') is distinct from 'number') then
      raise exception 'invalid_bank_snapshot' using errcode = '22023';
    end if;

    -- snapshotSeq הוא watermark שהלקוח באמת ראה אחרי sync של מאגר הצ'קים.
    -- אסור לשרת להקצות כאן sequence חדש: אירוע צ'ק מקביל שלא נצפה חייב להישאר אחרי ה-baseline.
    v_requested_snapshot_num := (v_bank->>'snapshotSeq')::numeric;
    if v_requested_snapshot_num < 0
       or v_requested_snapshot_num <> trunc(v_requested_snapshot_num)
       or v_requested_snapshot_num > 9223372036854775807::numeric then
      raise exception 'invalid_bank_snapshot_sequence' using errcode = '22023';
    end if;
    v_requested_snapshot_seq := v_requested_snapshot_num::bigint;

    if jsonb_typeof(v_old_bank->'snapshotSeq') = 'number' then
      begin
        v_old_snapshot_seq := greatest(0, (v_old_bank->>'snapshotSeq')::bigint);
      exception when others then
        raise exception 'invalid_existing_bank_snapshot_sequence' using errcode = '22023';
      end;
    end if;

    select coalesce(max((e.value->>'seq')::bigint), 0)
      into v_shared_max_seq
    from public.shared_checks_documents s
    left join lateral jsonb_array_elements(
      case when jsonb_typeof(s.state->'bankEvents')='array' then s.state->'bankEvents' else '[]'::jsonb end
    ) e(value) on true
    where s.owner_id = v_owner and s.document_name = 'main';
    v_shared_max_seq := coalesce(v_shared_max_seq, 0);

    if v_requested_snapshot_seq < v_old_snapshot_seq then
      raise exception 'stale_bank_snapshot_watermark'
        using errcode = 'PT409', hint = 'Refresh shared checks before saving a new bank snapshot.';
    end if;
    if v_requested_snapshot_seq > greatest(v_old_snapshot_seq, v_shared_max_seq) then
      raise exception 'bank_snapshot_watermark_ahead_of_server'
        using errcode = '22023', hint = 'The client watermark was not observed in shared check events.';
    end if;

    v_now := clock_timestamp();
    v_bank := v_bank || jsonb_build_object('snapshotSeq', v_requested_snapshot_seq);
    if v_bank->>'source' = 'manual' then
      v_bank := v_bank || jsonb_build_object('updatedAt', v_now);
    end if;
  elsif v_old_state is not null then
    -- Lightweight bank snapshot metadata is server-authoritative; ordinary Kupa saves cannot roll it back.
    v_bank := v_bank || jsonb_build_object(
      'snapshotToken', coalesce(v_old_bank->'snapshotToken','null'::jsonb),
      'snapshotSeq', coalesce(v_old_bank->'snapshotSeq','null'::jsonb),
      'updatedAt', case when v_bank->>'source' = 'manual' then coalesce(v_old_bank->'updatedAt','null'::jsonb) else 'null'::jsonb end
    );
  else
    v_bank := v_bank || jsonb_build_object('snapshotSeq', null);
  end if;

  -- Financial feeds and credit-company sync are stored in finance_sync_documents / bank_transactions,
  -- never in the Kupa document or its snapshot backups. Keep only the tiny Kupa-owned bank baseline metadata.
  v_bank := jsonb_build_object(
    'currentBalance', case when v_bank->>'source' = 'manual' then coalesce(v_bank->'currentBalance','null'::jsonb) else 'null'::jsonb end,
    'updatedAt', case when v_bank->>'source' = 'manual' then coalesce(v_bank->'updatedAt','null'::jsonb) else 'null'::jsonb end,
    'asOfDate', case when v_bank->>'source' = 'manual' then coalesce(v_bank->'asOfDate','null'::jsonb) else 'null'::jsonb end,
    'adjustments', coalesce(v_bank->'adjustments','[]'::jsonb),
    'source', case when v_bank->>'source' = 'manual' then 'manual'::text else null end,
    'sourceAccount', null,
    'snapshotToken', coalesce(v_bank->'snapshotToken','null'::jsonb),
    'snapshotSeq', coalesce(v_bank->'snapshotSeq','null'::jsonb)
  );
  v_server_state := (v_server_state - 'bank' - 'creditSync') || jsonb_build_object('bank', v_bank);

  if v_current_revision is null then
    if coalesce(p_expected_revision,0) <> 0 then
      raise exception 'revision_conflict' using errcode = 'PT409';
    end if;
    insert into public.kupa_documents(owner_id, document_name, revision, state, updated_at)
    values (v_owner, p_document_name, 1, v_server_state, now())
    returning kupa_documents.revision, kupa_documents.updated_at, kupa_documents.state
      into v_new_revision, v_new_updated_at, v_server_state;
    insert into public.kupa_periodic_backups(owner_id, document_name, revision, state, saved_at)
    values (v_owner, p_document_name, v_new_revision, v_server_state, v_new_updated_at)
    on conflict do nothing;
    return query select v_new_revision, v_new_updated_at, v_server_state;
    return;
  end if;

  -- ACK שאבד: קודם בודקים אם התוכן שכבר בשרת הוא בדיוק התוכן המבוקש.
  if v_old_state = v_server_state then
    return query select v_current_revision, v_old_updated_at, v_old_state;
    return;
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision_conflict' using errcode = 'PT409';
  end if;

  insert into public.kupa_document_backups(owner_id, document_name, revision, state, saved_at)
  values (v_owner, p_document_name, v_current_revision, v_old_state, v_old_updated_at)
  on conflict do nothing;

  update public.kupa_documents d
  set revision = d.revision + 1, state = v_server_state, updated_at = now()
  where d.owner_id = v_owner and d.document_name = p_document_name
  returning d.revision, d.updated_at, d.state
    into v_new_revision, v_new_updated_at, v_server_state;

  if not exists (
    select 1 from public.kupa_periodic_backups p
    where p.owner_id = v_owner and p.document_name = p_document_name
      and p.saved_at > now() - interval '12 hours'
  ) then
    insert into public.kupa_periodic_backups(owner_id, document_name, revision, state, saved_at)
    values (v_owner, p_document_name, v_new_revision, v_server_state, v_new_updated_at)
    on conflict do nothing;
  end if;

  return query select v_new_revision, v_new_updated_at, v_server_state;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.save_kupa_document_core(p_document_name text, p_expected_revision bigint, p_state jsonb, p_operation_id text, p_delete_intents jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal', 'extensions'
AS $function$
declare
  v_owner uuid:=auth.uid();
  v_allowed constant text[]:=array['credits','cash','rights','notes','expenses','notesSheet.rows','notesSheet.columns','notesSheet.sheets'];
  v_intents jsonb;
  v_payload_hash text;v_legacy_hash text;v_ledger_hash text;v_applied_revision bigint;
  v_saved_revision bigint;v_saved_updated_at timestamptz;v_saved_state jsonb;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if p_document_name is null or btrim(p_document_name)='' then raise exception 'invalid_document_name' using errcode='22023'; end if;
  if p_expected_revision is null or p_expected_revision<0 then raise exception 'invalid_expected_revision' using errcode='22023'; end if;
  if p_state is null or jsonb_typeof(p_state) is distinct from 'object' then raise exception 'invalid_kupa_state' using errcode='22023'; end if;
  if coalesce(btrim(p_operation_id),'')='' or length(p_operation_id)>200 then raise exception 'invalid_operation_id' using errcode='22023'; end if;
  v_intents:=netunim_internal.canonical_delete_intents(coalesce(p_delete_intents,'{}'::jsonb),v_allowed);
  if not pg_try_advisory_xact_lock(hashtextextended('netunim_financial_write:'||v_owner::text,0)) then raise exception 'save_busy' using errcode='PT429'; end if;
  perform set_config('lock_timeout','100ms',true);
  v_payload_hash:=encode(extensions.digest(convert_to(jsonb_build_object('state',p_state,'deleteIntents',v_intents)::text,'UTF8'),'sha256'),'hex');
  v_legacy_hash:=encode(extensions.digest(convert_to(p_state::text,'UTF8'),'sha256'),'hex');
  select o.payload_sha256,o.applied_revision into v_ledger_hash,v_applied_revision from netunim_internal.document_sync_operations o
  where o.owner_id=v_owner and o.domain='kupa' and o.document_name=p_document_name and o.operation_id=p_operation_id;
  if found then
    if v_ledger_hash<>v_payload_hash and v_ledger_hash<>v_legacy_hash then raise exception 'idempotency_key_reuse' using errcode='PT422'; end if;
    select d.revision,d.updated_at,d.state into revision,updated_at,state from public.kupa_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
    if revision is null then raise exception 'operation_replay_document_missing' using errcode='P0002'; end if;
    operation_replayed:=true;operation_revision:=v_applied_revision;return next;return;
  end if;
  perform set_config('app.kupa_delete_intents',v_intents::text,true);
  begin
    select x.revision,x.updated_at,x.state into v_saved_revision,v_saved_updated_at,v_saved_state
    from netunim_internal.save_kupa_document(p_document_name,p_expected_revision,p_state) x;
  exception when lock_not_available then raise exception 'save_busy' using errcode='PT429'; end;
  if v_saved_revision is null then raise exception 'save_result_missing' using errcode='P0002'; end if;
  insert into netunim_internal.document_sync_operations(owner_id,domain,document_name,operation_id,payload_sha256,applied_revision,created_at)
  values(v_owner,'kupa',p_document_name,p_operation_id,v_payload_hash,v_saved_revision,coalesce(v_saved_updated_at,now()));
  select d.revision,d.updated_at,d.state into revision,updated_at,state from public.kupa_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
  operation_replayed:=false;operation_revision:=v_saved_revision;return next;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.save_kupa_document_current(p_document_name text, p_expected_revision bigint, p_state jsonb, p_operation_id text, p_delete_intents jsonb, p_audit jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_owner uuid:=auth.uid();v_before jsonb;v_result record;v_paths text[]:=array['credits','cash','rights','notes','expenses','cards','notesSheet.rows','notesSheet.columns','notesSheet.sheets'];
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
  perform netunim_internal.assert_document_invariants('kupa',p_state);
  select d.state into v_before from public.kupa_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
  perform set_config('app.kupa_cards_delete_intents',coalesce(p_delete_intents->'cards','[]'::jsonb)::text,true);
  select * into v_result from netunim_internal.save_kupa_document_core(p_document_name,p_expected_revision,p_state,p_operation_id,coalesce(p_delete_intents,'{}'::jsonb)-'cards');
  perform set_config('app.kupa_cards_delete_intents','[]',true);
  perform netunim_internal.record_operation_audit(v_owner,'kupa',p_document_name,p_operation_id,coalesce(p_audit,'{}'::jsonb)||jsonb_build_object('baseRevision',p_expected_revision),coalesce(v_before,p_state),v_result.state,v_paths,null);
  return query select v_result.revision,v_result.updated_at,v_result.state,v_result.operation_replayed,v_result.operation_revision;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.save_order_management_document(p_document_name text, p_expected_revision bigint, p_state jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_owner uuid := auth.uid();
  v_current_revision bigint;
  v_old_state jsonb;
  v_old_updated_at timestamptz;
  v_new_revision bigint;
  v_new_updated_at timestamptz;
begin
  if v_owner is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  if p_document_name is null or btrim(p_document_name) = '' then
    raise exception 'invalid_document_name' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'invalid_expected_revision' using errcode = '22023';
  end if;
  if p_state is null
     or jsonb_typeof(p_state) is distinct from 'object'
     or (p_state ? 'checks')
     or jsonb_typeof(p_state->'suppliers') is distinct from 'array'
     or jsonb_typeof(p_state->'transactions') is distinct from 'array'
     or jsonb_typeof(p_state->'customerDebts') is distinct from 'array'
     or jsonb_typeof(p_state->'customerOrders') is distinct from 'array'
     or jsonb_typeof(p_state->'serviceCalls') is distinct from 'array'
     or jsonb_typeof(p_state->'inventoryItems') is distinct from 'array'
     or jsonb_typeof(p_state->'inventoryCategoryOrder') is distinct from 'array'
     or jsonb_typeof(p_state->'inventoryEvents') is distinct from 'array'
     or jsonb_typeof(p_state->'warehouseOrders') is distinct from 'array'
     or jsonb_typeof(p_state->'notes') is distinct from 'array' then
    raise exception 'invalid_order_management_state'
      using errcode = '22023',
            hint = 'Post-cutover order state is missing required arrays or still contains checks.';
  end if;

  perform set_config('app.order_management_rpc_write', '1', true);

  -- Distributed fail-fast writer gate: do not let concurrent stale clients queue on the row lock
  -- and exhaust PostgREST's database pool. The transaction-scoped lock releases automatically.
  if not pg_try_advisory_xact_lock(
    hashtextextended('order_management:' || v_owner::text || ':' || p_document_name, 0)
  ) then
    raise exception 'revision_conflict'
      using errcode = 'PT409',
            hint = 'Another save for this document is already in progress; refresh the revision before retrying.';
  end if;

  select d.revision, d.state, d.updated_at
    into v_current_revision, v_old_state, v_old_updated_at
  from public.order_management_documents d
  where d.owner_id = v_owner and d.document_name = p_document_name
  for update;

  if v_current_revision is null then
    if coalesce(p_expected_revision,0) <> 0 then
      raise exception 'revision_conflict' using errcode = 'PT409';
    end if;
    insert into public.order_management_documents(owner_id, document_name, revision, state, updated_at)
    values (v_owner, p_document_name, 1, p_state, now())
    returning order_management_documents.revision, order_management_documents.updated_at
      into v_new_revision, v_new_updated_at;
    insert into public.order_management_periodic_backups(owner_id, document_name, revision, state, saved_at)
    values (v_owner, p_document_name, v_new_revision, p_state, v_new_updated_at)
    on conflict do nothing;
    return query select v_new_revision, v_new_updated_at;
    return;
  end if;

  -- savedAt משתנה בכל prepareState ולכן אינו חלק מהשוואת התוכן העסקי.
  -- הבדיקה קודמת ל-revision conflict כדי לתמוך ב-retry לאחר ACK שאבד.
  if (v_old_state #- '{_meta,savedAt}') = (p_state #- '{_meta,savedAt}') then
    return query select v_current_revision, v_old_updated_at;
    return;
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision_conflict' using errcode = 'PT409';
  end if;

  insert into public.order_management_document_backups(owner_id, document_name, revision, state, saved_at)
  values (v_owner, p_document_name, v_current_revision, v_old_state, v_old_updated_at)
  on conflict do nothing;

  update public.order_management_documents d
  set revision=d.revision+1, state=p_state, updated_at=now()
  where d.owner_id=v_owner and d.document_name=p_document_name
  returning d.revision, d.updated_at into v_new_revision, v_new_updated_at;

  if not exists (
    select 1 from public.order_management_periodic_backups p
    where p.owner_id=v_owner and p.document_name=p_document_name
      and p.saved_at > now() - interval '12 hours'
  ) then
    insert into public.order_management_periodic_backups(owner_id, document_name, revision, state, saved_at)
    values (v_owner, p_document_name, v_new_revision, p_state, v_new_updated_at)
    on conflict do nothing;
  end if;

  return query select v_new_revision, v_new_updated_at;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.save_order_management_document_core(p_document_name text, p_expected_revision bigint, p_state jsonb, p_operation_id text, p_delete_intents jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal', 'extensions'
AS $function$
declare
  v_owner uuid:=auth.uid();
  v_allowed constant text[]:=array['suppliers','transactions','customerDebts','customerOrders','serviceCalls','notes','inventoryItems','inventoryEvents','warehouseOrders','notesSheet.sheets','notesSheet.columns','notesSheet.rows'];
  v_intents jsonb;
  v_payload_hash text;v_legacy_hash text;v_ledger_hash text;v_applied_revision bigint;
  v_saved_revision bigint;v_saved_updated_at timestamptz;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if p_document_name is null or btrim(p_document_name)='' then raise exception 'invalid_document_name' using errcode='22023'; end if;
  if p_expected_revision is null or p_expected_revision<0 then raise exception 'invalid_expected_revision' using errcode='22023'; end if;
  if p_state is null or jsonb_typeof(p_state) is distinct from 'object' then raise exception 'invalid_order_management_state' using errcode='22023'; end if;
  if coalesce(btrim(p_operation_id),'')='' or length(p_operation_id)>200 then raise exception 'invalid_operation_id' using errcode='22023'; end if;
  v_intents:=netunim_internal.canonical_delete_intents(coalesce(p_delete_intents,'{}'::jsonb),v_allowed);
  if not pg_try_advisory_xact_lock(hashtextextended('order_management:'||v_owner::text||':'||p_document_name,0)) then
    raise exception 'save_busy' using errcode='PT429',hint='Another save is already in progress. Retry later without refreshing the revision.';
  end if;
  perform set_config('lock_timeout','100ms',true);
  v_payload_hash:=encode(extensions.digest(convert_to(jsonb_build_object('state',p_state,'deleteIntents',v_intents)::text,'UTF8'),'sha256'),'hex');
  v_legacy_hash:=encode(extensions.digest(convert_to(p_state::text,'UTF8'),'sha256'),'hex');
  select o.payload_sha256,o.applied_revision into v_ledger_hash,v_applied_revision
  from netunim_internal.document_sync_operations o
  where o.owner_id=v_owner and o.domain='orders' and o.document_name=p_document_name and o.operation_id=p_operation_id;
  if found then
    if v_ledger_hash<>v_payload_hash and v_ledger_hash<>v_legacy_hash then raise exception 'idempotency_key_reuse' using errcode='PT422'; end if;
    select d.revision,d.updated_at,d.state into revision,updated_at,state from public.order_management_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
    if revision is null then raise exception 'operation_replay_document_missing' using errcode='P0002'; end if;
    operation_replayed:=true;operation_revision:=v_applied_revision;return next;return;
  end if;
  perform set_config('app.order_management_delete_intents',v_intents::text,true);
  begin
    select x.revision,x.updated_at into v_saved_revision,v_saved_updated_at
    from netunim_internal.save_order_management_document(p_document_name,p_expected_revision,p_state) x;
  exception when lock_not_available then raise exception 'save_busy' using errcode='PT429'; end;
  if v_saved_revision is null then raise exception 'save_result_missing' using errcode='P0002'; end if;
  insert into netunim_internal.document_sync_operations(owner_id,domain,document_name,operation_id,payload_sha256,applied_revision,created_at)
  values(v_owner,'orders',p_document_name,p_operation_id,v_payload_hash,v_saved_revision,coalesce(v_saved_updated_at,now()));
  select d.revision,d.updated_at,d.state into revision,updated_at,state from public.order_management_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
  operation_replayed:=false;operation_revision:=v_saved_revision;return next;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.save_order_management_document_current(p_document_name text, p_expected_revision bigint, p_state jsonb, p_operation_id text, p_delete_intents jsonb, p_audit jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_owner uuid:=auth.uid();v_before jsonb;v_result record;v_paths text[]:=array['suppliers','transactions','customerDebts','customerOrders','serviceCalls','notes','inventoryItems','inventoryEvents','warehouseOrders','notesSheet.sheets','notesSheet.columns','notesSheet.rows'];
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
  perform netunim_internal.assert_document_invariants('orders',p_state);
  select d.state into v_before from public.order_management_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
  select * into v_result from netunim_internal.save_order_management_document_core(p_document_name,p_expected_revision,p_state,p_operation_id,p_delete_intents);
  perform netunim_internal.record_operation_audit(v_owner,'orders',p_document_name,p_operation_id,coalesce(p_audit,'{}'::jsonb)||jsonb_build_object('baseRevision',p_expected_revision),coalesce(v_before,p_state),v_result.state,v_paths,null);
  return query select v_result.revision,v_result.updated_at,v_result.state,v_result.operation_replayed,v_result.operation_revision;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.save_shared_checks_document(p_document_name text, p_expected_revision bigint, p_state jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_owner uuid := auth.uid();
  v_current_revision bigint;
  v_old_state jsonb;
  v_old_updated_at timestamptz;
  v_server_state jsonb;
  v_server_checks jsonb := '[]'::jsonb;
  v_bank_events jsonb := '[]'::jsonb;
  v_check jsonb;
  v_old_check jsonb;
  v_check_id text;
  v_status text;
  v_old_status text;
  v_is_deposited boolean;
  v_was_deposited boolean;
  v_old_effect numeric;
  v_new_effect numeric;
  v_effect_delta numeric;
  v_event_seq bigint;
  v_now timestamptz;
  v_new_revision bigint;
  v_new_updated_at timestamptz;
begin
  if v_owner is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  if p_document_name is null or btrim(p_document_name) = '' then
    raise exception 'invalid_document_name' using errcode = '22023';
  end if;
  if p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'invalid_expected_revision' using errcode = '22023';
  end if;
  if p_state is null
     or jsonb_typeof(p_state) is distinct from 'object'
     or jsonb_typeof(p_state->'checks') is distinct from 'array' then
    raise exception 'invalid_shared_checks_state'
      using errcode = '22023', hint = 'State must be an object containing a checks array.';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_state->'checks') c
    where jsonb_typeof(c) is distinct from 'object'
       or nullif(btrim(c->>'id'), '') is null
       or jsonb_typeof(c->'amount') is distinct from 'number'
       or jsonb_typeof(c->'dueDate') is distinct from 'string'
       or jsonb_typeof(c->'status') is distinct from 'string'
       or (c->>'status') not in ('בקופה','הופקד - במעקב','נפרע','חזר','בוטל')
  ) then
    raise exception 'invalid_shared_check_record' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_state->'checks') c
    group by c->>'id'
    having count(*) > 1
  ) then
    raise exception 'duplicate_shared_check_id' using errcode = '23505';
  end if;

  perform set_config('app.shared_checks_rpc_write', '1', true);

  select d.revision, d.state, d.updated_at
    into v_current_revision, v_old_state, v_old_updated_at
  from public.shared_checks_documents d
  where d.owner_id = v_owner and d.document_name = p_document_name
  for update;

  if v_old_state is not null and jsonb_typeof(v_old_state->'bankEvents') = 'array' then
    v_bank_events := v_old_state->'bankEvents';
  end if;

  -- Fail closed against a stale/bootstrap client interpreting an empty local shell as "delete every check".
  -- Normal single-record deletion remains available, including deletion of the final remaining check.
  if v_old_state is not null
     and jsonb_typeof(v_old_state->'checks') = 'array'
     and jsonb_array_length(v_old_state->'checks') > 1
     and jsonb_array_length(p_state->'checks') = 0
     and nullif(current_setting('app.shared_checks_delete_ids', true), '') is null then
    raise exception 'bulk_delete_all_shared_checks_forbidden'
      using errcode = '22023', hint = 'Refresh from shared_checks_documents before attempting a bulk deletion.';
  end if;

  -- הלקוח שולח את מצב הצ'קים בלבד. depositSeq/depositedAt ו-bankEvents הם server-authoritative.
  -- כל שינוי בהשפעה הכספית של צ'ק יוצר אירוע delta מונוטוני, כולל החזרה, שינוי סכום ומחיקה.
  for v_check in select value from jsonb_array_elements(p_state->'checks') loop
    v_check_id := v_check->>'id';
    v_status := v_check->>'status';
    v_is_deposited := v_status in ('הופקד - במעקב','נפרע');
    v_old_check := null;
    if v_old_state is not null then
      select c.value into v_old_check
      from jsonb_array_elements(v_old_state->'checks') c(value)
      where c.value->>'id' = v_check_id
      limit 1;
    end if;
    v_old_status := coalesce(v_old_check->>'status','');
    v_was_deposited := v_old_status in ('הופקד - במעקב','נפרע');
    v_old_effect := case when v_was_deposited then coalesce((v_old_check->>'amount')::numeric,0) else 0 end;
    v_new_effect := case when v_is_deposited then coalesce((v_check->>'amount')::numeric,0) else 0 end;
    v_effect_delta := v_new_effect - v_old_effect;
    v_event_seq := null;
    v_now := null;

    -- כל metadata שהלקוח החזיר מנוקה ומוחזר מהמצב השרת/מהאירוע החדש בלבד.
    v_check := v_check - 'depositSeq' - 'depositedAt' - 'bankEvents';

    if v_is_deposited and not v_was_deposited then
      v_event_seq := nextval('public.shared_financial_event_seq');
      v_now := clock_timestamp();
      v_check := v_check || jsonb_build_object('depositSeq', v_event_seq, 'depositedAt', v_now);
    elsif v_old_check is not null then
      -- retry אחרי ACK שאבד מקבל שוב בדיוק את metadata שכבר אושר בשרת.
      v_check := v_check || jsonb_build_object(
        'depositSeq', coalesce(v_old_check->'depositSeq','null'::jsonb),
        'depositedAt', coalesce(v_old_check->'depositedAt','null'::jsonb)
      );
    else
      v_check := v_check || jsonb_build_object('depositSeq', null, 'depositedAt', null);
    end if;

    if v_effect_delta <> 0 then
      if v_event_seq is null then
        v_event_seq := nextval('public.shared_financial_event_seq');
        v_now := clock_timestamp();
      end if;
      v_bank_events := v_bank_events || jsonb_build_array(jsonb_build_object(
        'seq', v_event_seq,
        'at', v_now,
        'delta', v_effect_delta,
        'kind', 'check_effect_delta',
        'checkId', v_check_id
      ));
    end if;

    v_server_checks := v_server_checks || jsonb_build_array(v_check);
  end loop;

  -- מחיקת צ'ק בעל השפעה בנקאית חייבת ליצור reversal גם לאחר שהרשומה עצמה נעלמה.
  if v_old_state is not null then
    for v_old_check in
      select c.value
      from jsonb_array_elements(v_old_state->'checks') c(value)
      where not exists (
        select 1 from jsonb_array_elements(p_state->'checks') n(value)
        where n.value->>'id' = c.value->>'id'
      )
    loop
      v_old_status := coalesce(v_old_check->>'status','');
      if v_old_status in ('הופקד - במעקב','נפרע') then
        v_old_effect := coalesce((v_old_check->>'amount')::numeric,0);
        if v_old_effect <> 0 then
          v_event_seq := nextval('public.shared_financial_event_seq');
          v_now := clock_timestamp();
          v_bank_events := v_bank_events || jsonb_build_array(jsonb_build_object(
            'seq', v_event_seq,
            'at', v_now,
            'delta', -v_old_effect,
            'kind', 'check_effect_delta',
            'checkId', v_old_check->>'id'
          ));
        end if;
      end if;
    end loop;
  end if;

  v_server_state := jsonb_build_object('version',1,'checks',v_server_checks,'bankEvents',v_bank_events);

  if v_current_revision is null then
    if coalesce(p_expected_revision, 0) <> 0 then
      raise exception 'revision_conflict' using errcode = 'PT409';
    end if;
    insert into public.shared_checks_documents(owner_id, document_name, revision, state, updated_at)
    values (v_owner, p_document_name, 1, v_server_state, now())
    returning shared_checks_documents.revision, shared_checks_documents.updated_at, shared_checks_documents.state
      into v_new_revision, v_new_updated_at, v_server_state;
    insert into public.shared_checks_periodic_backups(owner_id, document_name, revision, state, saved_at)
    values (v_owner, p_document_name, v_new_revision, v_server_state, v_new_updated_at)
    on conflict do nothing;
    return query select v_new_revision, v_new_updated_at, v_server_state;
    return;
  end if;

  -- Idempotency לפני conflict: lost ACK עם expected revision ישן אינו יוצר כשל שווא.
  if v_old_state = v_server_state then
    return query select v_current_revision, v_old_updated_at, v_old_state;
    return;
  end if;
  if v_current_revision <> p_expected_revision then
    raise exception 'revision_conflict' using errcode = 'PT409';
  end if;

  insert into public.shared_checks_document_backups(owner_id, document_name, revision, state, saved_at)
  values (v_owner, p_document_name, v_current_revision, v_old_state, v_old_updated_at)
  on conflict do nothing;

  update public.shared_checks_documents d
  set revision = d.revision + 1, state = v_server_state, updated_at = now()
  where d.owner_id = v_owner and d.document_name = p_document_name
  returning d.revision, d.updated_at, d.state
    into v_new_revision, v_new_updated_at, v_server_state;

  if not exists (
    select 1 from public.shared_checks_periodic_backups p
    where p.owner_id = v_owner and p.document_name = p_document_name
      and p.saved_at > now() - interval '12 hours'
  ) then
    insert into public.shared_checks_periodic_backups(owner_id, document_name, revision, state, saved_at)
    values (v_owner, p_document_name, v_new_revision, v_server_state, v_new_updated_at)
    on conflict do nothing;
  end if;

  return query select v_new_revision, v_new_updated_at, v_server_state;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.save_shared_checks_document_core(p_document_name text, p_expected_revision bigint, p_state jsonb, p_operation_id text, p_deleted_check_ids jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal', 'extensions'
AS $function$
declare
  v_owner uuid:=auth.uid();
  v_deleted_ids jsonb:='[]'::jsonb;
  v_payload_hash text;
  v_legacy_payload_hash text;
  v_ledger_hash text;
  v_applied_revision bigint;
  v_saved_revision bigint;
  v_saved_updated_at timestamptz;
  v_saved_state jsonb;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if p_document_name is null or btrim(p_document_name)='' then raise exception 'invalid_document_name' using errcode='22023'; end if;
  if p_expected_revision is null or p_expected_revision<0 then raise exception 'invalid_expected_revision' using errcode='22023'; end if;
  if p_state is null or jsonb_typeof(p_state) is distinct from 'object' then raise exception 'invalid_shared_checks_state' using errcode='22023'; end if;
  if coalesce(btrim(p_operation_id),'')='' or length(p_operation_id)>200 then raise exception 'invalid_operation_id' using errcode='22023'; end if;
  if p_deleted_check_ids is null or jsonb_typeof(p_deleted_check_ids) is distinct from 'array' then raise exception 'invalid_shared_checks_delete_intent' using errcode='22023'; end if;
  if exists (
    select 1 from jsonb_array_elements(p_deleted_check_ids) j(value)
    where jsonb_typeof(j.value) is distinct from 'string'
       or nullif(btrim(j.value #>> '{}'),'') is null
  ) then
    raise exception 'invalid_shared_checks_delete_intent' using errcode='22023';
  end if;

  select coalesce(jsonb_agg(id order by id),'[]'::jsonb)
    into v_deleted_ids
  from (
    select distinct btrim(j.value #>> '{}') as id
    from jsonb_array_elements(p_deleted_check_ids) j(value)
  ) declared;
  if jsonb_array_length(v_deleted_ids) <> jsonb_array_length(p_deleted_check_ids) then
    raise exception 'duplicate_shared_checks_delete_intent' using errcode='22023';
  end if;

  if not pg_try_advisory_xact_lock(hashtextextended('netunim_financial_write:'||v_owner::text,0)) then
    raise exception 'save_busy' using errcode='PT429',hint='Another financial save is already in progress. Retry later.';
  end if;
  perform set_config('lock_timeout','100ms',true);

  v_payload_hash:=encode(extensions.digest(convert_to(jsonb_build_object('state',p_state,'deletedCheckIds',v_deleted_ids)::text,'UTF8'),'sha256'),'hex');
  v_legacy_payload_hash:=encode(extensions.digest(convert_to(p_state::text,'UTF8'),'sha256'),'hex');
  select o.payload_sha256,o.applied_revision into v_ledger_hash,v_applied_revision
  from netunim_internal.document_sync_operations o
  where o.owner_id=v_owner and o.domain='shared-checks' and o.document_name=p_document_name and o.operation_id=p_operation_id;
  if found then
    if v_ledger_hash<>v_payload_hash and v_ledger_hash<>v_legacy_payload_hash then
      raise exception 'idempotency_key_reuse' using errcode='PT422',hint='An operation id cannot be reused with a different payload.';
    end if;
    select d.revision,d.updated_at,d.state into revision,updated_at,state
    from public.shared_checks_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
    if revision is null then raise exception 'operation_replay_document_missing' using errcode='P0002'; end if;
    operation_replayed:=true;operation_revision:=v_applied_revision;return next;return;
  end if;

  perform set_config('app.shared_checks_delete_ids',v_deleted_ids::text,true);
  begin
    select x.revision,x.updated_at,x.state into v_saved_revision,v_saved_updated_at,v_saved_state
    from netunim_internal.save_shared_checks_document(p_document_name,p_expected_revision,p_state) x;
  exception when lock_not_available then
    raise exception 'save_busy' using errcode='PT429',hint='A financial row is temporarily locked. Retry later.';
  end;
  if v_saved_revision is null then raise exception 'save_result_missing' using errcode='P0002'; end if;

  insert into netunim_internal.document_sync_operations(owner_id,domain,document_name,operation_id,payload_sha256,applied_revision,created_at)
  values(v_owner,'shared-checks',p_document_name,p_operation_id,v_payload_hash,v_saved_revision,coalesce(v_saved_updated_at,now()));
  select d.revision,d.updated_at,d.state into revision,updated_at,state
  from public.shared_checks_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
  operation_replayed:=false;operation_revision:=v_saved_revision;return next;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.save_shared_checks_document_current(p_document_name text, p_expected_revision bigint, p_state jsonb, p_operation_id text, p_deleted_check_ids jsonb, p_audit jsonb)
 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_owner uuid:=auth.uid();v_before jsonb;v_result record;v_paths text[]:=array['checks'];
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
  if jsonb_typeof(p_state->'bankEvents') is distinct from 'array' then p_state:=p_state||jsonb_build_object('bankEvents','[]'::jsonb);end if;
  perform netunim_internal.assert_document_invariants('shared-checks',p_state);
  select d.state into v_before from public.shared_checks_documents d where d.owner_id=v_owner and d.document_name=p_document_name;
  select * into v_result from netunim_internal.save_shared_checks_document_core(p_document_name,p_expected_revision,p_state,p_operation_id,p_deleted_check_ids);
  perform netunim_internal.record_operation_audit(v_owner,'shared-checks',p_document_name,p_operation_id,coalesce(p_audit,'{}'::jsonb)||jsonb_build_object('baseRevision',p_expected_revision),coalesce(v_before,p_state),v_result.state,v_paths,null);
  return query select v_result.revision,v_result.updated_at,v_result.state,v_result.operation_replayed,v_result.operation_revision;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.shared_checks_delete_intent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_raw text;
  v_declared_json jsonb;
  v_declared text[] := '{}'::text[];
  v_removed text[] := '{}'::text[];
begin
  if tg_op <> 'UPDATE' then return new; end if;
  if jsonb_typeof(old.state->'checks') is distinct from 'array'
     or jsonb_typeof(new.state->'checks') is distinct from 'array' then
    raise exception 'invalid_shared_checks_state' using errcode='22023';
  end if;

  select coalesce(array_agg(id order by id),'{}'::text[])
    into v_removed
  from (
    select old_check.value->>'id' as id
    from jsonb_array_elements(old.state->'checks') old_check(value)
    where nullif(btrim(old_check.value->>'id'),'') is not null
      and not exists (
        select 1
        from jsonb_array_elements(new.state->'checks') new_check(value)
        where new_check.value->>'id' = old_check.value->>'id'
      )
  ) removed;

  if cardinality(v_removed)=0 then return new; end if;

  v_raw:=nullif(current_setting('app.shared_checks_delete_ids',true),'');
  if v_raw is null then
    raise exception 'shared_checks_delete_intent_required'
      using errcode='PT422', hint='Check deletion requires an explicit deletedCheckIds list.';
  end if;

  begin
    v_declared_json:=v_raw::jsonb;
  exception when others then
    raise exception 'invalid_shared_checks_delete_intent' using errcode='22023';
  end;
  if jsonb_typeof(v_declared_json) is distinct from 'array' then
    raise exception 'invalid_shared_checks_delete_intent' using errcode='22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_declared_json) j(value)
    where jsonb_typeof(j.value) is distinct from 'string'
       or nullif(btrim(j.value #>> '{}'),'') is null
  ) then
    raise exception 'invalid_shared_checks_delete_intent' using errcode='22023';
  end if;

  select coalesce(array_agg(id order by id),'{}'::text[])
    into v_declared
  from (
    select distinct btrim(j.value #>> '{}') as id
    from jsonb_array_elements(v_declared_json) j(value)
  ) declared;

  if cardinality(v_declared) <> jsonb_array_length(v_declared_json) then
    raise exception 'duplicate_shared_checks_delete_intent' using errcode='22023';
  end if;
  if v_declared is distinct from v_removed then
    raise exception 'shared_checks_delete_intent_mismatch'
      using errcode='PT422', hint='deletedCheckIds must exactly match the check IDs removed by this update.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.spreadsheet_legacy_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare source netunim_internal.spreadsheet_legacy_sources%rowtype;v_domain text;v_book jsonb;v_safe boolean;
begin
  if old.state->>'notesWorkbookExternal' is distinct from '1' then return new;end if;
  v_domain:=case when tg_table_name='kupa_documents' then 'kupa' else 'orders' end;
  if new.state?'notesSheet' then
    select * into source from netunim_internal.spreadsheet_legacy_sources s where s.owner_id=old.owner_id and s.domain=v_domain and s.document_name=old.document_name;
    v_book:=new.state->'notesSheet';
    v_safe:=v_book=source.source_state or v_book=source.migrated_state or v_book=netunim_internal.empty_spreadsheet();
    if not found or source.migrated_at<now()-interval '90 days' or not coalesce(v_safe,false)
    then raise exception 'spreadsheet_upgrade_required' using errcode='PT409',hint='Refresh the app. The independent workbook is safe; this old client cannot edit it.';end if;
    new.state:=new.state-'notesSheet';
  end if;
  new.state:=new.state||'{"notesWorkbookExternal":1}'::jsonb;return new;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.stage_restore_group_current(p_restore_group_id uuid, p_app_site text, p_main_document_name text, p_main_base_revision bigint, p_main_state jsonb, p_main_delete_intents jsonb, p_checks_document_name text, p_checks_base_revision bigint, p_checks_state jsonb, p_checks_delete_ids jsonb, p_main_operation_id text, p_checks_operation_id text, p_audit jsonb)
 RETURNS TABLE(restore_group_id uuid, phase text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'netunim_internal', 'extensions'
AS $function$
declare v_owner uuid:=auth.uid();v_main_hash text;v_checks_hash text;v_existing netunim_internal.restore_operation_groups%rowtype;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
  if p_restore_group_id is null or p_app_site not in ('kupa','orders') or p_main_base_revision<0 then raise exception 'invalid_restore_group' using errcode='22023';end if;
  perform netunim_internal.assert_document_invariants(p_app_site,p_main_state);
  if p_checks_state is not null then
    if jsonb_typeof(p_checks_state->'bankEvents') is distinct from 'array' then p_checks_state:=p_checks_state||jsonb_build_object('bankEvents','[]'::jsonb);end if;
    perform netunim_internal.assert_document_invariants('shared-checks',p_checks_state);
    if p_checks_base_revision is null or p_checks_base_revision<0 or coalesce(btrim(p_checks_operation_id),'')='' then raise exception 'invalid_restore_checks_target' using errcode='22023';end if;
  end if;
  if coalesce(btrim(p_main_operation_id),'')='' then raise exception 'invalid_restore_operation_id' using errcode='22023';end if;
  v_main_hash:=encode(extensions.digest(convert_to(jsonb_build_object('state',p_main_state,'deleteIntents',coalesce(p_main_delete_intents,'{}'::jsonb))::text,'UTF8'),'sha256'),'hex');
  v_checks_hash:=case when p_checks_state is null then null else encode(extensions.digest(convert_to(jsonb_build_object('state',p_checks_state,'deleteIds',coalesce(p_checks_delete_ids,'[]'::jsonb))::text,'UTF8'),'sha256'),'hex') end;
  insert into netunim_internal.restore_operation_groups(owner_id,restore_group_id,app_site,main_document_name,main_base_revision,checks_document_name,checks_base_revision,main_state,checks_state,main_delete_intents,checks_delete_ids,main_payload_sha256,checks_payload_sha256,main_operation_id,checks_operation_id,phase,audit)
  values(v_owner,p_restore_group_id,p_app_site,p_main_document_name,p_main_base_revision,coalesce(nullif(p_checks_document_name,''),'main'),p_checks_base_revision,p_main_state,p_checks_state,coalesce(p_main_delete_intents,'{}'::jsonb),coalesce(p_checks_delete_ids,'[]'::jsonb),v_main_hash,v_checks_hash,p_main_operation_id,p_checks_operation_id,'staged',coalesce(p_audit,'{}'::jsonb))
  on conflict do nothing;
  select * into v_existing from netunim_internal.restore_operation_groups g where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  if v_existing.main_payload_sha256<>v_main_hash or v_existing.checks_payload_sha256 is distinct from v_checks_hash or v_existing.app_site<>p_app_site then
    raise exception 'restore_group_id_reuse' using errcode='PT422';
  end if;
  return query select v_existing.restore_group_id,v_existing.phase;
end
$function$

CREATE OR REPLACE FUNCTION netunim_internal.track_kupa_core_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.core_updated_at := coalesce(new.core_updated_at, new.updated_at, clock_timestamp());
  elsif netunim_internal.kupa_header_owned_state(new.state)
        is distinct from netunim_internal.kupa_header_owned_state(old.state) then
    new.core_updated_at := coalesce(new.updated_at, clock_timestamp());
  else
    -- Finance/bank bookkeeping may still advance revision + updated_at for concurrency safety.
    -- Preserve the Kupa-owned clock so the top header does not pretend user data changed.
    new.core_updated_at := old.core_updated_at;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION netunim_internal.upgrade_legacy_spreadsheet(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare v_book jsonb;v_sheets jsonb;v_columns jsonb;v_rows jsonb;v_v2 boolean:=coalesce((p_source->>'version')::int,1)>=2;
begin
  if jsonb_typeof(p_source->'columns') is distinct from 'array' or jsonb_typeof(p_source->'rows') is distinct from 'array' then raise exception 'invalid_legacy_spreadsheet' using errcode='22023';end if;
  if p_source?'version' and p_source->'version' not in ('1'::jsonb,'2'::jsonb) then raise exception 'invalid_legacy_spreadsheet_version' using errcode='22023';end if;
  perform netunim_internal.assert_entity_array_ids(p_source,array['columns'],true);
  perform netunim_internal.assert_entity_array_ids(p_source,array['rows'],true);
  if v_v2 then perform netunim_internal.assert_entity_array_ids(p_source,array['sheets'],true);end if;
  if not v_v2 and p_source->'columns'='[]'::jsonb and p_source->'rows'='[]'::jsonb then return netunim_internal.empty_spreadsheet();end if;
  v_sheets:=case when v_v2 then p_source->'sheets' else '[{"id":"sheet-main","name":"גליון 1"}]'::jsonb end;
  select coalesce(jsonb_agg(jsonb_build_object('id',c->>'id','sheetId',case when v_v2 then c->>'sheetId' else 'sheet-main' end,'title',coalesce(c->>'title','עמודה '||n),'type',coalesce(c->>'type','text'),'width',case when v_v2 then coalesce(c->'width','90'::jsonb) else '90'::jsonb end) order by n),'[]'::jsonb) into v_columns from jsonb_array_elements(p_source->'columns') with ordinality x(c,n);
  select coalesce(jsonb_agg(jsonb_build_object('id',r->>'id','sheetId',case when v_v2 then r->>'sheetId' else 'sheet-main' end,'cells',r->'cells','createdAt',coalesce(r->>'createdAt',''),'updatedAt',coalesce(r->>'updatedAt',r->>'createdAt','')) order by n),'[]'::jsonb) into v_rows from jsonb_array_elements(p_source->'rows') with ordinality x(r,n);
  v_book:=jsonb_build_object('version',2,'sheets',v_sheets,'columns',v_columns,'rows',v_rows);
  -- No filtering, re-parenting, duplicate repair or unknown-cell removal.
  perform netunim_internal.assert_spreadsheet(v_book);return v_book;
end
$function$

CREATE OR REPLACE FUNCTION public.acknowledge_bank_transaction_alert(p_transaction_id bigint, p_alert_kind text)
 RETURNS TABLE(transaction_id bigint, alert_kind text, acknowledged_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_owner uuid:=auth.uid();
  v_kind text:=btrim(coalesce(p_alert_kind,''));
  v_at timestamptz:=now();
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if p_transaction_id is null or p_transaction_id<=0 then raise exception 'invalid_bank_transaction_id' using errcode='22023'; end if;
  if v_kind not in ('returned_cheque') then raise exception 'unsupported_bank_alert_kind' using errcode='22023'; end if;

  update public.bank_transactions b
     set alert_acknowledgements=coalesce(b.alert_acknowledgements,'{}'::jsonb) || jsonb_build_object(v_kind,v_at)
   where b.id=p_transaction_id and b.owner_id=v_owner
  returning b.id into transaction_id;

  if transaction_id is null then
    raise exception 'bank_alert_transaction_not_found'
      using errcode='P0002',hint='The bank transaction does not exist or is not owned by this user.';
  end if;

  alert_kind:=v_kind;
  acknowledged_at:=v_at;
  return next;
end $function$

CREATE OR REPLACE FUNCTION public.acknowledge_bank_transaction_missing(p_transaction_id bigint)
 RETURNS TABLE(transaction_id bigint, acknowledged_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_owner uuid:=auth.uid();
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if p_transaction_id is null or p_transaction_id<=0 then raise exception 'invalid_bank_transaction_id' using errcode='22023'; end if;

  update public.bank_transactions b
     set missing_acknowledged_at=coalesce(b.missing_acknowledged_at,now())
   where b.id=p_transaction_id and b.owner_id=v_owner and b.presence_state='missing'
  returning b.id,b.missing_acknowledged_at into transaction_id,acknowledged_at;

  if transaction_id is null then
    raise exception 'bank_missing_transaction_not_found'
      using errcode='P0002',hint='The row is not a missing bank transaction owned by this user.';
  end if;
  return next;
end $function$

CREATE OR REPLACE FUNCTION public.activate_storage_protocol_v2(p_orders_revision bigint, p_kupa_revision bigint, p_shared_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare
  v_owner uuid:=auth.uid();v_count integer;v_orders bigint;v_kupa bigint;v_shared bigint;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
  if p_orders_revision is null or p_orders_revision<1 or p_kupa_revision is null or p_kupa_revision<1
     or p_shared_revision is null or p_shared_revision<1 then
    raise exception 'storage_protocol_revisions_required' using errcode='22023';
  end if;
  -- Same advisory-lock order as ordinary Orders then financial writes. This
  -- serializes activation with saves before comparing the supplied heads.
  perform pg_advisory_xact_lock(hashtextextended('order_management:'||v_owner::text||':suppliers',0));
  perform pg_advisory_xact_lock(hashtextextended('netunim_financial_write:'||v_owner::text,0));
  select count(*) into v_count from netunim_internal.storage_writer_protocol where owner_id=v_owner;
  if v_count=3 then return public.get_storage_protocol_state();end if;
  if v_count<>0 then raise exception 'storage_protocol_partial_activation' using errcode='PT409';end if;
  if exists(select 1 from netunim_internal.restore_operation_groups g where g.owner_id=v_owner and g.phase<>'completed') then
    raise exception 'storage_protocol_restore_pending' using errcode='PT409';
  end if;
  select d.revision into v_orders from public.order_management_documents d
    where d.owner_id=v_owner and d.document_name='suppliers';
  select d.revision into v_kupa from public.kupa_documents d
    where d.owner_id=v_owner and d.document_name='main';
  select d.revision into v_shared from public.shared_checks_documents d
    where d.owner_id=v_owner and d.document_name='main';
  if v_orders is distinct from p_orders_revision or v_kupa is distinct from p_kupa_revision
     or v_shared is distinct from p_shared_revision then
    raise exception 'storage_protocol_cloud_heads_changed' using errcode='PT409';
  end if;
  insert into netunim_internal.storage_writer_protocol
    (owner_id,domain,min_writer_protocol,activated_revision,activated_by)
  values (v_owner,'orders',2,v_orders,v_owner),
         (v_owner,'kupa',2,v_kupa,v_owner),
         (v_owner,'shared-checks',2,v_shared,v_owner);
  return public.get_storage_protocol_state();
end
$function$

CREATE OR REPLACE FUNCTION public.apply_restore_group_v5(p_restore_group_id uuid)
 RETURNS TABLE(restore_group_id uuid, phase text, main_revision bigint, checks_revision bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_owner uuid:=auth.uid();v_group netunim_internal.restore_operation_groups%rowtype;v_main record;v_checks record;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501';end if;
  select * into v_group from netunim_internal.restore_operation_groups g where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id for update;
  if not found then raise exception 'restore_group_missing' using errcode='P0002';end if;
  if v_group.phase='completed' then
    select applied_revision into main_revision from netunim_internal.document_sync_operations where owner_id=v_owner and domain=v_group.app_site and document_name=v_group.main_document_name and operation_id=v_group.main_operation_id;
    if v_group.checks_state is not null then select applied_revision into checks_revision from netunim_internal.document_sync_operations where owner_id=v_owner and domain='shared-checks' and document_name=v_group.checks_document_name and operation_id=v_group.checks_operation_id;end if;
    restore_group_id:=v_group.restore_group_id;phase:=v_group.phase;return next;return;
  end if;
  perform set_config('app.destructive_operation_kind','restore',true);
  -- Failed applies deliberately leave the last durable phase unchanged: this entire
  -- function is atomic, so an exception also rolls back phase bookkeeping. Operators
  -- must monitor the failed RPC/database log, not infer a durable error from this row.
  update netunim_internal.restore_operation_groups as g set phase='main_pending',updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  perform netunim_internal.capture_safety_snapshot(v_owner,v_group.app_site,v_group.main_document_name,v_group.main_operation_id,'restore',v_group.restore_group_id);
  if v_group.app_site='orders' then
    select * into v_main from public.save_order_management_document_v5(v_group.main_document_name,v_group.main_base_revision,v_group.main_state,v_group.main_operation_id,v_group.main_delete_intents,v_group.audit||jsonb_build_object('mutationType','restore','restoreGroupId',v_group.restore_group_id));
  else
    select * into v_main from public.save_kupa_document_v5(v_group.main_document_name,v_group.main_base_revision,v_group.main_state,v_group.main_operation_id,v_group.main_delete_intents,v_group.audit||jsonb_build_object('mutationType','restore','restoreGroupId',v_group.restore_group_id));
  end if;
  update netunim_internal.restore_operation_groups as g set phase='main_acked',updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  if v_group.checks_state is not null then
    update netunim_internal.restore_operation_groups as g set phase='checks_pending',updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
    perform netunim_internal.capture_safety_snapshot(v_owner,'shared-checks',v_group.checks_document_name,v_group.checks_operation_id,'restore',v_group.restore_group_id);
    select * into v_checks from public.save_shared_checks_document_v5(v_group.checks_document_name,v_group.checks_base_revision,v_group.checks_state,v_group.checks_operation_id,v_group.checks_delete_ids,v_group.audit||jsonb_build_object('mutationType','restore','restoreGroupId',v_group.restore_group_id));
    update netunim_internal.restore_operation_groups as g set phase='checks_acked',updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  end if;
  perform set_config('app.destructive_operation_kind','',true);
  update netunim_internal.restore_operation_groups as g set phase='completed',completed_at=now(),updated_at=now() where g.owner_id=v_owner and g.restore_group_id=p_restore_group_id;
  restore_group_id:=v_group.restore_group_id;phase:='completed';main_revision:=v_main.revision;
  checks_revision:=null;
  if v_group.checks_state is not null then checks_revision:=v_checks.revision;end if;
  return next;
end
$function$

CREATE OR REPLACE FUNCTION public.apply_restore_group_v6(p_restore_group_id uuid)
 RETURNS TABLE(restore_group_id uuid, phase text, main_revision bigint, checks_revision bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal'
AS $function$
declare v_app text;
begin
  select g.app_site into v_app from netunim_internal.restore_operation_groups g
    where g.owner_id=auth.uid() and g.restore_group_id=p_restore_group_id;
  if v_app not in ('orders','kupa') or v_app is null then
    raise exception 'restore_group_missing' using errcode='P0002';
  end if;
  perform netunim_internal.enter_storage_writer_v2(v_app);
  perform netunim_internal.enter_storage_writer_v2('shared-checks');
