 RETURNS TABLE(revision bigint, updated_at timestamp with time zone, state jsonb, operation_replayed boolean, operation_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'netunim_internal', 'extensions'
AS $function$
